const lessons = [
{"num": 2, "time": "00:00:30,000 --> 00:00:34,980", "arabic": "وَأَفْقَهُنَا، دُلَّنَا عَلَى سَبِيلٍ لِنُصْرَةِ دِينِنَا، وَنَحْنُ مَعَكَ.", "segs": null, "full_uz": "Va bizning eng bilimdonimiz, dinimizga yordam berish yo'lini ko'rsating, biz siz bilanmiz.", "note": null},
{"num": 5, "time": "00:00:34,980 --> 00:00:54,500", "arabic": "لَقَدْ وَصَلَتِ الصَّفَاقَةُ بِقَاضِي قُضَاةِ الْوَاثِقِ أَحْمَدَ بْنِ أَبِي دُؤَادٍ أَنْ عَمَّمَ عَلَى الْقُضَاةِ بِأَنْ يُفَرِّقُوا بَيْنَ الرَّجُلِ الَّذِي لَا يَقُولُ بِخَلْقِ الْقُرْآنِ وَبَيْنَ امْرَأَتِهِ.", "segs": [{"ar": "لَقَدْ وَصَلَتِ الصَّفَاقَةُ بِقَاضِي قُضَاةِ الْوَاثِقِ أَحْمَدَ بْنِ أَبِي دُؤَادٍ", "uz": "Vosiqning qozilar qozisi Ahmad ibn Abi Du'odning beadabligi shu darajaga yetdiki,"}, {"ar": "أَنْ عَمَّمَ عَلَى الْقُضَاةِ", "uz": "u qozilarga buyurib chiqdi:"}, {"ar": "بِأَنْ يُفَرِّقُوا بَيْنَ الرَّجُلِ الَّذِي لَا يَقُولُ بِخَلْقِ الْقُرْآنِ وَبَيْنَ امْرَأَتِهِ.", "uz": "Qur'onning yaratilganligini aytmaydigan erkakni xotinidan ajratishlarini."}], "full_uz": "Vosiqning qozilar qozisi Ahmad ibn Abi Du'odning beadabligi shu darajaga yetdiki, u qozilarga Qur'onning yaratilganligini aytmaydigan erkakni xotinidan ajratishlarini buyurib chiqdi.", "note": null},
{"num": 10, "time": "00:00:54,500 --> 00:01:09,099", "arabic": "إِنْ رُفِعَتْ لَهُمْ أَحْوَالُ مَنْ يَرْفُضُونَ الْقَوْلَ بِهَذِهِ الْمَسْأَلَةِ، إِنْ لَمْ نَنْصُرِ الْحَقَّ الْيَوْمَ فَلَنْ تَجِدَ الْأَجْيَالُ حَقًّا تَنْصُرُهُ.", "segs": [{"ar": "إِنْ رُفِعَتْ لَهُمْ أَحْوَالُ مَنْ يَرْفُضُونَ الْقَوْلَ بِهَذِهِ الْمَسْأَلَةِ،", "uz": "Agar bu masalada gapirishdan bosh tortganlarning ahvoli ularga yetkazilsa... Agar"}, {"ar": "إِنْ لَمْ نَنْصُرِ الْحَقَّ الْيَوْمَ", "uz": "bugun haqqa yordam bermasak,"}, {"ar": "فَلَنْ تَجِدَ الْأَجْيَالُ حَقًّا تَنْصُرُهُ.", "uz": "kelajak avlodlar yordam beradigan haq topa olmaydi."}], "full_uz": "Agar bu masalada gapirishdan bosh tortganlarning ahvoli ularga yetkazilsa... Agar bugun haqqa yordam bermasak, kelajak avlodlar yordam beradigan haq topa olmaydi.", "note": null},
{"num": 13, "time": "00:01:09,099 --> 00:01:12,500", "arabic": "فَمَا الَّذِي تَرَاهُ يَا إِمَامُ؟", "segs": null, "full_uz": "Nima deb bilasiz, Imom?", "note": null},
{"num": 14, "time": "00:01:13,500 --> 00:01:48,819", "arabic": "لَقَدْ تَأَمَّلْتُ طَوِيلًا فِيمَا آلَ إِلَيْهِ حَالُ الْأُمَّةِ، فَالسُّلْطَانُ وَمَنْ مَعَهُ مِنَ الْمُعْتَزِلَةِ مُجْتَهِدُونَ غَايَةَ الِاجْتِهَادِ فِي نَشْرِ بِدْعَتِهِمْ، فِي الْمُقَابِلِ لَا بُدَّ مِنْ جَمَاعَةٍ تَسْتَشْعِرُ حَجْمَ الْمُصِيبَةِ الَّتِي حَلَّتْ، وَتَجْتَهِدُ فِي مُقَاوَمَةِ الْبِدْعَةِ وَنَشْرِ السُّنَّةِ، تَأْمُرُ بِالْمَعْرُوفِ وَتَنْهَى عَنِ الْمُنْكَرِ، حَتَّى تَنْهَضَ الْأُمَّةُ مِنْ كَبْوَتِهَا وَتَقْوَى بَعْدَ ضَعْفِهَا.", "segs": [{"ar": "لَقَدْ تَأَمَّلْتُ طَوِيلًا فِيمَا آلَ إِلَيْهِ حَالُ الْأُمَّةِ،", "uz": "Ummatning holati qanday yakunga kelganini uzoq mulohaza qildim,"}, {"ar": "فَالسُّلْطَانُ وَمَنْ مَعَهُ مِنَ الْمُعْتَزِلَةِ مُجْتَهِدُونَ غَايَةَ الِاجْتِهَادِ فِي نَشْرِ بِدْعَتِهِمْ،", "uz": "sulton va u bilan birga bo'lgan Mu'tazila o'z bid'atlarini tarqatishda intilishning cho'qqisidalar,"}, {"ar": "فِي الْمُقَابِلِ لَا بُدَّ مِنْ جَمَاعَةٍ تَسْتَشْعِرُ حَجْمَ الْمُصِيبَةِ الَّتِي حَلَّتْ،", "uz": "bunga qarshi esa yuz bergan falokatning kattaligini his qiladigan bir jamoa bo'lishi shart,"}, {"ar": "وَتَجْتَهِدُ فِي مُقَاوَمَةِ الْبِدْعَةِ وَنَشْرِ السُّنَّةِ، تَأْمُرُ بِالْمَعْرُوفِ وَتَنْهَى عَنِ الْمُنْكَرِ،", "uz": "bid'atga qarshi kurashib, sunnatni tarqatadigan, yaxshilikka buyuradigan va yomonlikdan qaytaradigan,"}, {"ar": "حَتَّى تَنْهَضَ الْأُمَّةُ مِنْ كَبْوَتِهَا وَتَقْوَى بَعْدَ ضَعْفِهَا.", "uz": "toki ummat yiqilishidan turib, zaiflashgandan keyin kuchga kirsin."}], "full_uz": "Ummatning holati qanday yakunga kelganini uzoq mulohaza qildim. Sulton va u bilan birga bo'lgan Mu'tazila o'z bid'atlarini tarqatishda intilishning cho'qqisidalar. Bunga qarshi esa yuz bergan falokatning kattaligini his qiladigan, bid'atga qarshi kurashib, sunnatni tarqatishga intiladigan bir jamoa bo'lishi shart — yaxshilikka buyuradigan va yomonlikdan qaytaradigan, toki ummat yiqilishidan turib, zaiflashgandan keyin kuchga kirsin.", "note": null},
{"num": 21, "time": "00:01:48,819 --> 00:01:54,359", "arabic": "أَصَبْتَ، جَزَاكَ اللَّهُ عَنِ الْإِسْلَامِ وَالْمُسْلِمِينَ خَيْرًا.", "segs": null, "full_uz": "To'g'ri aytdingiz, Alloh sizga Islom va musulmonlar nomidan yaxshilik bersin.", "note": null},
{"num": 23, "time": "00:01:54,359 --> 00:01:58,799", "arabic": "وَنَحْنُ مَعَكَ يَا إِمَامُ ضِدَّ أَهْلِ الْبِدَعِ وَالضَّلَالِ.", "segs": null, "full_uz": "Va biz sizning tarafingizdamiz, Imom, bid'at va adashuv ahliga qarshi.", "note": null},
{"num": 24, "time": "00:01:58,799 --> 00:02:03,359", "arabic": "بَارَكَ اللَّهُ فِيكَ يَا أَبَا أَحْمَدَ.", "segs": null, "full_uz": "Alloh senga barakot bersin, ey Abu Ahmad.", "note": null},
{"num": 25, "time": "00:02:03,359 --> 00:02:15,919", "arabic": "سَيَكُونُ اجْتِمَاعُنَا بَيْنَ فَتْرَةٍ وَأُخْرَى، لِنَتَدَارَسَ فِيمَا بَيْنَنَا الْأُمُورَ، وَنَتَحَرَّكَ بَيْنَ النَّاسِ لِتَحْذِيرِهِمْ مِنْ ضَلَالَاتِ الْمُعْتَزِلَةِ.", "segs": [{"ar": "سَيَكُونُ اجْتِمَاعُنَا بَيْنَ فَتْرَةٍ وَأُخْرَى،", "uz": "Bizning yig'ilishimiz vaqti-vaqti bilan bo'lib turadi,"}, {"ar": "لِنَتَدَارَسَ فِيمَا بَيْنَنَا الْأُمُورَ،", "uz": "o'zaro ishlarni muhokama qilib,"}, {"ar": "وَنَتَحَرَّكَ بَيْنَ النَّاسِ لِتَحْذِيرِهِمْ مِنْ ضَلَالَاتِ الْمُعْتَزِلَةِ.", "uz": "odamlar orasida yurib, ularni Mu'tazilaning adashuvlaridan ogohlantiramiz."}], "full_uz": "Bizning yig'ilishimiz vaqti-vaqti bilan bo'lib turadi, o'zaro ishlarni muhokama qilib, odamlar orasida yurib, ularni Mu'tazilaning adashuvlaridan ogohlantiramiz.", "note": null},
{"num": 29, "time": "00:02:15,919 --> 00:02:26,939", "arabic": "وَلَكِنِ احْذَرُوا مَنْ دُونَكُمْ مِمَّنْ لَا تَثِقُونَ بِهِمْ، مِنْ أَتْبَاعِ الْمُعْتَزِلَةِ وَعُيُونِ الْوَاثِقِ.", "segs": [{"ar": "وَلَكِنِ احْذَرُوا مَنْ دُونَكُمْ مِمَّنْ لَا تَثِقُونَ بِهِمْ،", "uz": "Lekin ishonmagan kishilaringizdan — Mu'tazila izdoshlari va"}, {"ar": "مِنْ أَتْبَاعِ الْمُعْتَزِلَةِ وَعُيُونِ الْوَاثِقِ.", "uz": "Vosiqning ko'zchilaridan — ehtiyot bo'ling."}], "full_uz": "Lekin ishonmagan kishilaringizdan — Mu'tazila izdoshlari va Vosiqning ko'zchilaridan — ehtiyot bo'ling.", "note": null},
{"num": 33, "time": "00:02:26,939 --> 00:02:30,060", "arabic": "لَا إِلَهَ إِلَّا اللَّهُ، مُحَمَّدٌ رَسُولُ اللَّهِ.", "segs": null, "full_uz": "Allohdan boshqa iloh yo'q, Muhammad Uning Rasulidir.", "note": null},
{"num": 35, "time": "00:02:45,919 --> 00:02:53,259", "arabic": "لَوْ عَرَفْتُ أَنَّكَ لَنْ تَعْمَلَ فِي الدُّكَّانِ، لَكُنْتُ أَعْطَيْتُهُ لِأَبِي وَلَأَخَذْتُ الثَّمَنَ عِوَضًا عَنْهُ.", "segs": [{"ar": "لَوْ عَرَفْتُ أَنَّكَ لَنْ تَعْمَلَ فِي الدُّكَّانِ،", "uz": "Do'konda ishlamasligingni bilganimda, uni otamga berib,"}, {"ar": "لَكُنْتُ أَعْطَيْتُهُ لِأَبِي وَلَأَخَذْتُ الثَّمَنَ عِوَضًا عَنْهُ.", "uz": "o'rniga pulini olgan bo'lardim."}], "full_uz": "Do'konda ishlamasligingni bilganimda, uni otamga berib, o'rniga pulini olgan bo'lardim.", "note": null},
{"num": 37, "time": "00:02:53,259 --> 00:03:00,759", "arabic": "لَمْ أَقُلْ إِنَّنِي لَنْ أَعْمَلَ فِي الدُّكَّانِ، وَلَكِنْ شَغَلَنِي شَاغِلٌ هَذِهِ الْأَيَّامَ فَحَسْبُ، وَبَعْدَهَا سَأَتَفَرَّغُ لَكَ وَلِلدُّكَّانِ.", "segs": [{"ar": "لَمْ أَقُلْ إِنَّنِي لَنْ أَعْمَلَ فِي الدُّكَّانِ،", "uz": "Do'konda ishlamayman demadim, faqat shu kunlarda bir"}, {"ar": "وَلَكِنْ شَغَلَنِي شَاغِلٌ هَذِهِ الْأَيَّامَ فَحَسْبُ،", "uz": "ish meni band qilyapti,"}, {"ar": "وَبَعْدَهَا سَأَتَفَرَّغُ لَكَ وَلِلدُّكَّانِ.", "uz": "undan keyin senga va do'konga bag'ishlanaman."}], "full_uz": "Do'konda ishlamayman demadim, faqat shu kunlarda bir ish meni band qilyapti, undan keyin senga va do'konga bag'ishlanaman.", "note": null},
{"num": 40, "time": "00:03:00,759 --> 00:03:06,779", "arabic": "وَمَا الَّذِي يَشْغَلُكَ حَتَّى تَنْصَرِفَ عَنْ مَوْرِدِ رِزْقِكَ؟", "segs": null, "full_uz": "Rizq manbaingdan yuz o'girguncha seni nima band qilyapti?", "note": null},
{"num": 41, "time": "00:03:06,779 --> 00:03:11,779", "arabic": "أَبُوكَ عَلَى حَقٍّ يَا عُمَرُ، إِنَّكَ مُنْذُ فَتْرَةٍ وَأَنْتَ لَسْتَ كَمَا عَاهَدْتَنَا.", "segs": [{"ar": "أَبُوكَ عَلَى حَقٍّ يَا عُمَرُ،", "uz": "Otang haq, Umar,"}, {"ar": "إِنَّكَ مُنْذُ فَتْرَةٍ وَأَنْتَ لَسْتَ كَمَا عَاهَدْتَنَا.", "uz": "bir muddatdan beri sen bizga va'da bergan kishi emassan."}], "full_uz": "Otang haq, Umar, bir muddatdan beri sen bizga va'da bergan kishi emassan.", "note": null},
{"num": 43, "time": "00:03:11,779 --> 00:03:14,159", "arabic": "هَلْ تُخْفِي شَيْئًا عَنِّي يَا وَلَدِي؟", "segs": null, "full_uz": "Mendan biror narsani yashiryapsanmi, o'g'lim?", "note": null},
{"num": 44, "time": "00:03:14,159 --> 00:03:15,699", "arabic": "وَمَا الَّذِي سَأُخْفِيهِ عَنْكُمْ؟", "segs": null, "full_uz": "Sizlardan nimani yashiraman?", "note": null},
{"num": 45, "time": "00:03:15,699 --> 00:03:17,799", "arabic": "تُجِيبُ عَنِ السُّؤَالِ بِسُؤَالٍ يَا عُمَرُ.", "segs": null, "full_uz": "Savolga savol bilan javob beryapsan, Umar.", "note": null},
{"num": 46, "time": "00:03:17,799 --> 00:03:20,959", "arabic": "مَا عِنْدِي قُلْتُهُ لَكُمْ وَلَكِنَّكُمْ لَا تُصَدِّقُونَ.", "segs": null, "full_uz": "Bilganimni sizga aytdim, lekin ishonmayapsizlar.", "note": null},
{"num": 47, "time": "00:03:20,959 --> 00:03:30,679", "arabic": "لَا فَائِدَةَ مِنْهُ يَا أُمَّ عُمَيْرٍ، ابْنُكِ هَذَا ثَعْلَبٌ مُرَاوِغٌ وَذِئْبٌ مَاكِرٌ، لَنْ تَأْخُذِي مِنْهُ حَقًّا وَلَا بَاطِلًا.", "segs": [{"ar": "لَا فَائِدَةَ مِنْهُ يَا أُمَّ عُمَيْرٍ،", "uz": "Undan foyda yo'q, ey Umayrning onasi,"}, {"ar": "ابْنُكِ هَذَا ثَعْلَبٌ مُرَاوِغٌ وَذِئْبٌ مَاكِرٌ،", "uz": "bu o'g'ling ayyor tulki va makkor bo'ri,"}, {"ar": "لَنْ تَأْخُذِي مِنْهُ حَقًّا وَلَا بَاطِلًا.", "uz": "undan na haq, na botil gap ola olasan."}], "full_uz": "Undan foyda yo'q, ey Umayrning onasi, bu o'g'ling ayyor tulki va makkor bo'ri, undan na haq, na botil gap ola olasan.", "note": null},
{"num": 50, "time": "00:03:30,679 --> 00:03:33,379", "arabic": "أَصْدَقَ أَبُوكَ الْقَوْلَ يَا عُمَيْرُ.", "segs": null, "full_uz": "Otang rost aytdi, Umayr.", "note": null},
{"num": 51, "time": "00:03:33,379 --> 00:03:38,859", "arabic": "وَأَسِرَّ إِلَيَّ أَنْتَ مُتَزَوِّجٌ مِنْ أُخْرَى أَمْ لَا.", "segs": null, "full_uz": "Va menga sirlicha ayt: boshqasiga uylanganmisan yoki yo'q.", "note": null},
{"num": 52, "time": "00:03:38,859 --> 00:03:43,659", "arabic": "مَا بِكِ؟ تَعْرِفِينَ أَنَّ أَبِي لَا يَكُفُّ عَنِ الْمِزَاحِ.", "segs": null, "full_uz": "Senga nima bo'ldi? Bilasan-ku, dadam hazildan to'xtamaydi.", "note": null},
{"num": 53, "time": "00:03:45,699 --> 00:03:53,280", "arabic": "إِذَنْ فَالْأَمْرُ كَمَا خَمَّنْتُ، أَنْتَ مُتَزَوِّجٌ بِأُخْرَى بَعْدَ أَنْ أَصْبَحَ الْمَالُ يَتَرَاقَصُ بَيْنَ يَدَيْكَ.", "segs": [{"ar": "إِذَنْ فَالْأَمْرُ كَمَا خَمَّنْتُ،", "uz": "Unda ish men taxmin qilganday,"}, {"ar": "أَنْتَ مُتَزَوِّجٌ بِأُخْرَى بَعْدَ أَنْ أَصْبَحَ الْمَالُ يَتَرَاقَصُ بَيْنَ يَدَيْكَ.", "uz": "sen mol-davlat qo'lingda o'ynay boshlagach, boshqasiga uylanibsan."}], "full_uz": "Unda ish men taxmin qilganday, sen mol-davlat qo'lingda o'ynay boshlagach, boshqasiga uylanibsan.", "note": null},
{"num": 55, "time": "00:03:53,280 --> 00:03:56,379", "arabic": "حَسَنًا حَسَنًا يَا أَبِي كَمَا تَشَاءُ.", "segs": null, "full_uz": "Xo'p, xo'p, dadajon, xohlaganingizcha.", "note": null},
{"num": 56, "time": "00:03:56,379 --> 00:04:00,099", "arabic": "الِابْنُ سِرُّ أَبِيهِ، وَمَنْ شَابَهَ أَبَاهُ فَمَا ظَلَمَ.", "segs": null, "full_uz": "O'g'il otasining siridir, otasiga o'xshagan kishi zulm qilmagan bo'ladi.", "note": "\"من شابه أباه فما ظلم\" — otasiga o'xshagan farzand ayblanmaydi, degan ma'nodagi arab maqoli."},
{"num": 57, "time": "00:04:00,099 --> 00:04:03,699", "arabic": "فَهَلْ فَعَلْتَهَا أَنْتَ مِنْ قَبْلُ حَتَّى أَحْذُوَ حَذْوَكَ؟", "segs": null, "full_uz": "Xo'sh, siz ham buni ilgari qilganmisiz, sizga taqlid qilay?", "note": null},
{"num": 58, "time": "00:04:04,500 --> 00:04:06,060", "arabic": "أَنَا لَمْ يَكُنْ لَدَيَّ الْمَالُ.", "segs": null, "full_uz": "Menda pul yo'q edi.", "note": null},
{"num": 59, "time": "00:04:06,060 --> 00:04:11,379", "arabic": "آهِ يَا عُمَرُ، لَوْ كُنْتُ أَمْلِكُ مَالًا.", "segs": null, "full_uz": "Oh, Umar, mol-davlatga ega bo'lganimda edi.", "note": null},
{"num": 61, "time": "00:04:11,379 --> 00:04:15,679", "arabic": "تَقْصِدُ أَنَّهُ لَوْ كَانَ لَدَيْكَ الْمَالُ كُنْتَ سَتَتَزَوَّجُ؟", "segs": null, "full_uz": "Pulingiz bo'lganida uylangan bo'lardingiz demoqchimisiz?", "note": null},
{"num": 62, "time": "00:04:15,680 --> 00:04:19,199", "arabic": "انْظُرُوا انْظُرُوا إِلَى نَاكِرِ الْمَعْرُوفِ الْهَرِمِ هَذَا.", "segs": null, "full_uz": "Qarang, qarang, bu qari nomunosibga.", "note": null},
{"num": 63, "time": "00:04:19,199 --> 00:04:27,900", "arabic": "مَا قَصَدْتُ ذَلِكَ يَا أُمَّ عُمَيْرٍ، إِنَّمَا قَصْدِي لَوْ كُنْتُ أَمْلِكُ الْمَالَ لَأَرَيْتُكِ مِنَ الدُّنْيَا مَا تُحِبِّينَ.", "segs": [{"ar": "مَا قَصَدْتُ ذَلِكَ يَا أُمَّ عُمَيْرٍ،", "uz": "Buni nazarda tutmadim, ey Umayrning onasi,"}, {"ar": "إِنَّمَا قَصْدِي لَوْ كُنْتُ أَمْلِكُ الْمَالَ", "uz": "faqat aytmoqchimanki, mol-davlatga ega bo'lganimda,"}, {"ar": "لَأَرَيْتُكِ مِنَ الدُّنْيَا مَا تُحِبِّينَ.", "uz": "senga dunyoda yoqtirgan narsalaringni ko'rsatgan bo'lardim."}], "full_uz": "Buni nazarda tutmadim, ey Umayrning onasi, faqat aytmoqchimanki, mol-davlatga ega bo'lganimda, senga dunyoda yoqtirgan narsalaringni ko'rsatgan bo'lardim.", "note": null},
{"num": 66, "time": "00:04:27,900 --> 00:04:35,540", "arabic": "أَخِي وَأُمُّهُ بِخَيْرٍ وَلَا يَنْقُصُهُمْ إِلَّا رُؤْيَتُكَ بَيْنَهُمْ يَا أَبِي، لَوْ تَدْرِي كَمِ اشْتَقْتُ لِرُؤْيَةِ أَخِي عَبْدِ اللَّهِ.", "segs": [{"ar": "أَخِي وَأُمُّهُ بِخَيْرٍ", "uz": "Ukam va uning onasi sog'-omon,"}, {"ar": "وَلَا يَنْقُصُهُمْ إِلَّا رُؤْيَتُكَ بَيْنَهُمْ يَا أَبِي،", "uz": "ularga faqat sizni orasida ko'rish yetishmayapti,"}, {"ar": "لَوْ تَدْرِي كَمِ اشْتَقْتُ لِرُؤْيَةِ أَخِي عَبْدِ اللَّهِ.", "uz": "dadajon. Ukam Abdullohni ko'rishga qanchalik sog'inganimni bilsangiz edi."}], "full_uz": "Ukam va uning onasi sog'-omon, ularga faqat sizni orasida ko'rish yetishmayapti, dadajon. Ukam Abdullohni ko'rishga qanchalik sog'inganimni bilsangiz edi.", "note": null},
{"num": 68, "time": "00:04:35,540 --> 00:04:40,620", "arabic": "لَوْلَا خَشْيَتِي مِنَ الْعُيُونِ لَحَمَلْتُهُ مَعِي، وَلَكِنْ لَا أَسْتَطِيعُ أَنْ أُجَازِفَ بِذَلِكَ.", "segs": [{"ar": "لَوْلَا خَشْيَتِي مِنَ الْعُيُونِ لَحَمَلْتُهُ مَعِي،", "uz": "Ko'zchilardan qo'rqmasam edi, uni o'zim bilan olib kelgan bo'lardim,"}, {"ar": "وَلَكِنْ لَا أَسْتَطِيعُ أَنْ أُجَازِفَ بِذَلِكَ.", "uz": "lekin bunga tavakkal qila olmayman."}], "full_uz": "Ko'zchilardan qo'rqmasam edi, uni o'zim bilan olib kelgan bo'lardim, lekin bunga tavakkal qila olmayman.", "note": null},
{"num": 70, "time": "00:04:45,680 --> 00:04:56,000", "arabic": "مَا أَخْبَارُ بَغْدَادَ وَالشُّيُوخِ؟", "segs": null, "full_uz": "Bag'dod va shayxlardan qanday xabar bor?", "note": null},
{"num": 71, "time": "00:04:56,000 --> 00:05:08,879", "arabic": "مَا قِصَّةُ عُمَرَ؟", "segs": null, "full_uz": "Umarning voqeasi nima?", "note": null},
{"num": 72, "time": "00:05:08,879 --> 00:05:19,980", "arabic": "مَا عَادَ يَهْتَمُّ بِالدُّكَّانِ أَبَدًا، حَتَّى تَمِيمٌ ابْنُ عَمِّي شَفِيعٍ تَرَكَ الْعَمَلَ هُنَا، وَتَرَدَّدُوا كَثِيرًا عَلَى بَيْتِ ابْنِ نَصْرٍ الْخُزَاعِيِّ.", "segs": [{"ar": "مَا عَادَ يَهْتَمُّ بِالدُّكَّانِ أَبَدًا،", "uz": "U endi do'konga umuman qiziqmaydi,"}, {"ar": "حَتَّى تَمِيمٌ ابْنُ عَمِّي", "uz": "hatto amakivachcham Shafi'ning o'g'li Tamim ham"}, {"ar": "شَفِيعٍ تَرَكَ الْعَمَلَ هُنَا،", "uz": "bu yerdagi ishni tashlab ketdi,"}, {"ar": "وَتَرَدَّدُوا كَثِيرًا عَلَى بَيْتِ ابْنِ نَصْرٍ الْخُزَاعِيِّ.", "uz": "va ular Ibn Nasr al-Xuzoiyning uyiga tez-tez borib turishibdi."}], "full_uz": "U endi do'konga umuman qiziqmaydi, hatto amakivachcham Shafi'ning o'g'li Tamim ham bu yerdagi ishni tashlab ketdi, va ular Ibn Nasr al-Xuzoiyning uyiga tez-tez borib turishibdi.", "note": null},
{"num": 75, "time": "00:05:19,980 --> 00:05:38,500", "arabic": "فِيهِ مَا فِيهِ، أَنَّ بَعْضَ مَنْ أَثِقُ بِهِمْ مِنْ أَصْحَابِنَا أَخْبَرَنِي أَنَّ الْخُزَاعِيَّ يُبَيِّتُ أَمْرًا.", "segs": [{"ar": "فِيهِ مَا فِيهِ،", "uz": "Bu ishda nimadir bor,"}, {"ar": "أَنَّ بَعْضَ مَنْ أَثِقُ بِهِمْ مِنْ", "uz": "chunki ishongan ba'zi safdoshlarim menga"}, {"ar": "أَصْحَابِنَا أَخْبَرَنِي أَنَّ الْخُزَاعِيَّ يُبَيِّتُ أَمْرًا.", "uz": "al-Xuzoiy bir ishni tunda rejalashtirayotganini aytishdi."}], "full_uz": "Bu ishda nimadir bor, chunki ishongan ba'zi safdoshlarim menga al-Xuzoiy bir ishni tunda rejalashtirayotganini aytishdi.", "note": null},
{"num": 79, "time": "00:05:38,500 --> 00:05:47,500", "arabic": "مِثْلَ مَاذَا؟", "segs": null, "full_uz": "Masalan, nima?", "note": null},
{"num": 80, "time": "00:05:47,500 --> 00:05:54,800", "arabic": "فَهِمْتُ أَنَّ الْخُزَاعِيَّ وَمَنْ مَعَهُ يُرِيدُونَ التَّصَدِّيَ لِلْوَاثِقِ، وَالْقِيَامَ بِالْأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ.", "segs": [{"ar": "فَهِمْتُ أَنَّ الْخُزَاعِيَّ وَمَنْ مَعَهُ يُرِيدُونَ التَّصَدِّيَ لِلْوَاثِقِ،", "uz": "Tushunishimcha, al-Xuzoiy va uning safdoshlari Vosiqqa qarshi turishni,"}, {"ar": "وَالْقِيَامَ بِالْأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ.", "uz": "yaxshilikka buyurish va yomonlikdan qaytarishni amalga oshirishni istashyapti."}], "full_uz": "Tushunishimcha, al-Xuzoiy va uning safdoshlari Vosiqqa qarshi turishni, yaxshilikka buyurish va yomonlikdan qaytarishni amalga oshirishni istashyapti.", "note": null},
{"num": 82, "time": "00:05:54,800 --> 00:06:14,019", "arabic": "أَلَيْسَ فِي بَقَاءِ ابْنِ حَنْبَلٍ فِي بَغْدَادَ مُخَالَفَةٌ صَرِيحَةٌ لِأَوَامِرِ أَمِيرِ الْمُؤْمِنِينَ الْقَاطِعَةِ؟", "segs": [{"ar": "أَلَيْسَ فِي بَقَاءِ ابْنِ حَنْبَلٍ فِي", "uz": "Ibn Hanbalning Bag'dodda qolishi mo'minlar"}, {"ar": "بَغْدَادَ مُخَالَفَةٌ صَرِيحَةٌ لِأَوَامِرِ أَمِيرِ الْمُؤْمِنِينَ الْقَاطِعَةِ؟", "uz": "amirining qat'iy buyruqlariga ochiq zid emasmi?"}], "full_uz": "Ibn Hanbalning Bag'dodda qolishi mo'minlar amirining qat'iy buyruqlariga ochiq zid emasmi?", "note": null},
{"num": 84, "time": "00:06:14,019 --> 00:06:29,000", "arabic": "نَحْنُ عُمَّالُ أَمِيرِ الْمُؤْمِنِينَ، نَلْتَزِمُ أَوَامِرَهُ نَصًّا وَحَرْفًا، وَلَا نَأْتَمِرُ شَيْئًا لَمْ يَقُلْهُ لَنَا.", "segs": [{"ar": "نَحْنُ عُمَّالُ أَمِيرِ الْمُؤْمِنِينَ، نَلْتَزِمُ أَوَامِرَهُ نَصًّا وَحَرْفًا،", "uz": "Biz mo'minlar amirining amaldorlarimiz, uning buyruqlariga so'zma-so'z rioya qilamiz,"}, {"ar": "وَلَا نَأْتَمِرُ شَيْئًا لَمْ يَقُلْهُ لَنَا.", "uz": "va u bizga aytmagan narsani o'zimizdan qilmaymiz."}], "full_uz": "Biz mo'minlar amirining amaldorlarimiz, uning buyruqlariga so'zma-so'z rioya qilamiz, va u bizga aytmagan narsani o'zimizdan qilmaymiz.", "note": null},
{"num": 87, "time": "00:06:29,000 --> 00:06:52,400", "arabic": "مَا طَلَبَ مِنِّي أَمِيرُ الْمُؤْمِنِينَ أَنْ أَقْبِضَ عَلَى ابْنِ حَنْبَلٍ، نَجِيءَ بِهِ حَتَّى وَلَوْ كَانَ فِي آخِرِ الْأَرْضِ، أَمَّا وَمِثْلُ هَذَا الْأَمْرِ لَيْسَ بِيَدِي، فَلَنْ أَتَعَرَّضَ لِلرَّجُلِ حَتَّى وَلَوْ كَانَ جَالِسًا بَيْنَنَا، أَفَهِمْتَ مَا أَقُولُ؟", "segs": [{"ar": "مَا طَلَبَ مِنِّي أَمِيرُ الْمُؤْمِنِينَ أَنْ أَقْبِضَ عَلَى ابْنِ حَنْبَلٍ،", "uz": "Mo'minlar amiri mendan Ibn Hanbalni qo'lga olishimni so'ramadi,"}, {"ar": "نَجِيءَ بِهِ حَتَّى وَلَوْ كَانَ فِي آخِرِ الْأَرْضِ،", "uz": "agar so'ragan bo'lsa, hatto yer chekkasida bo'lsa ham uni olib kelamiz,"}, {"ar": "أَمَّا وَمِثْلُ هَذَا الْأَمْرِ لَيْسَ بِيَدِي،", "uz": "lekin bunday ish mening qo'limda bo'lmagan ekan,"}, {"ar": "فَلَنْ أَتَعَرَّضَ لِلرَّجُلِ حَتَّى وَلَوْ كَانَ جَالِسًا بَيْنَنَا، أَفَهِمْتَ مَا أَقُولُ؟", "uz": "u odamga hatto oramizda o'tirgan bo'lsa ham tegmayman. Aytganimni tushundingmi?"}], "full_uz": "Mo'minlar amiri mendan Ibn Hanbalni qo'lga olishimni so'ramadi — agar so'ragan bo'lsa, hatto yer chekkasida bo'lsa ham uni olib kelamiz. Lekin bunday ish mening qo'limda bo'lmagan ekan, u odamga hatto oramizda o'tirgan bo'lsa ham tegmayman. Aytganimni tushundingmi?", "note": null},
{"num": 94, "time": "00:06:54,040 --> 00:06:58,439", "arabic": "الرَّجُلُ الْمِصْرِيُّ أَبُو يَعْقُوبَ الْبُوَيْطِيُّ.", "segs": null, "full_uz": "Misrlik odam Abu Ya'qub al-Buvaytiy.", "note": null},
{"num": 96, "time": "00:06:58,439 --> 00:06:59,560", "arabic": "أَجَلْ.", "segs": null, "full_uz": "Ha.", "note": null},
{"num": 97, "time": "00:06:59,560 --> 00:07:17,960", "arabic": "طَلَبَ أَمِيرُ الْمُؤْمِنِينَ إِبْقَاءَهُ فِي السِّجْنِ إِلَى أَنْ يَمُوتَ، أَوْ أَنْ يُقِرَّ بِأَنَّ الْقُرْآنَ مَخْلُوقٌ فَيُفْرَجَ عَنْهُ.", "segs": [{"ar": "طَلَبَ أَمِيرُ الْمُؤْمِنِينَ إِبْقَاءَهُ فِي السِّجْنِ إِلَى أَنْ يَمُوتَ،", "uz": "Mo'minlar amiri uni o'lguncha qamoqda saqlashni talab qildi,"}, {"ar": "أَوْ أَنْ يُقِرَّ بِأَنَّ الْقُرْآنَ مَخْلُوقٌ فَيُفْرَجَ عَنْهُ.", "uz": "yoki Qur'onning yaratilganligini tan olsa, ozod qilishni."}], "full_uz": "Mo'minlar amiri uni o'lguncha qamoqda saqlashni yoki Qur'onning yaratilganligini tan olsa, ozod qilishni talab qildi.", "note": null},
{"num": 102, "time": "00:07:17,960 --> 00:07:20,000", "arabic": "لِمَاذَا تَقُولُ ذَلِكَ يَا حَنْبَلُ؟", "segs": null, "full_uz": "Buni nega aytyapsan, ey Hanbal?", "note": null},
{"num": 103, "time": "00:07:20,000 --> 00:07:25,040", "arabic": "أَيَسُرُّكَ أَنْ يَفْتَدِيَ أَمِيرُ الْمُؤْمِنِينَ أَسْرَى الْمُسْلِمِينَ؟", "segs": null, "full_uz": "Mo'minlar amirining musulmon asirlarni to'lov to'lab qutqarishi seni xursand qiladimi?", "note": null},
{"num": 106, "time": "00:07:25,040 --> 00:07:30,420", "arabic": "بَلْ لَيْسَ هُنَاكَ أَهْنَأُ عَلَى قَلْبِي مِنْ ذَلِكَ، لَوْلَا مَا فَعَلَهُ ابْنُ أَبِي دُؤَادٍ.", "segs": [{"ar": "بَلْ لَيْسَ هُنَاكَ أَهْنَأُ عَلَى قَلْبِي مِنْ ذَلِكَ،", "uz": "Aksincha, bundan qalbimga yoqimliroq narsa yo'q,"}, {"ar": "لَوْلَا مَا فَعَلَهُ ابْنُ أَبِي دُؤَادٍ.", "uz": "agar Ibn Abi Du'od qilgan ish bo'lmaganida."}], "full_uz": "Aksincha, bundan qalbimga yoqimliroq narsa yo'q, agar Ibn Abi Du'od qilgan ish bo'lmaganida.", "note": null},
{"num": 108, "time": "00:07:30,420 --> 00:07:33,319", "arabic": "وَمَا فَعَلَ؟", "segs": null, "full_uz": "Nima qildi?", "note": null},
{"num": 109, "time": "00:07:33,319 --> 00:07:43,540", "arabic": "أَمَرَ بِامْتِحَانِ أَسْرَى الْمُسْلِمِينَ عِنْدَ الرُّومِ، فَمَنْ قَالَ بِبِدْعَةِ خَلْقِ الْقُرْآنِ افْتُدِيَ، وَمَنِ امْتَنَعَ تُرِكَ أَسِيرًا.", "segs": [{"ar": "أَمَرَ بِامْتِحَانِ أَسْرَى الْمُسْلِمِينَ عِنْدَ الرُّومِ،", "uz": "Rumliklar oldidagi musulmon asirlarni sinovdan o'tkazishni buyurdi: kim"}, {"ar": "فَمَنْ قَالَ بِبِدْعَةِ خَلْقِ الْقُرْآنِ افْتُدِيَ،", "uz": "Qur'onning yaratilganligi bid'atini aytsa, to'lov to'lanib qutqariladi,"}, {"ar": "وَمَنِ امْتَنَعَ تُرِكَ أَسِيرًا.", "uz": "kim bosh tortsa, asir qoldiriladi."}], "full_uz": "Rumliklar oldidagi musulmon asirlarni sinovdan o'tkazishni buyurdi: kim Qur'onning yaratilganligi bid'atini aytsa, to'lov to'lanib qutqariladi, kim bosh tortsa, asir qoldiriladi.", "note": null},
{"num": 112, "time": "00:07:43,540 --> 00:07:47,700", "arabic": "تَعْسًا لَهُ إِنْ كَانَ ذَلِكَ حَقًّا.", "segs": null, "full_uz": "Agar bu rost bo'lsa, unga halokat bo'lsin.", "note": null},
{"num": 113, "time": "00:07:47,700 --> 00:07:53,899", "arabic": "أَلَا تَقَاوِيلُ فِي أَزْمِنَةِ الْفِتْنَةِ كَثِيرَةٌ يَا بُنَيَّ؟ فَتَثَبَّتْ.", "segs": null, "full_uz": "Fitna zamonlarida gap-so'zlar ko'p bo'lmaydimi, o'g'lim? Ishonch hosil qil.", "note": null},
{"num": 115, "time": "00:07:53,899 --> 00:07:58,019", "arabic": "تَثَبَّتْنَا يَا إِمَامُ، وَعَلِمْنَا أَنَّهَا أَخْبَارٌ صَحِيحَةٌ.", "segs": null, "full_uz": "Ishonch hosil qildik, Imom, va bu to'g'ri xabar ekanini bilib oldik.", "note": null},
{"num": 117, "time": "00:08:00,019 --> 00:08:12,979", "arabic": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ، حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ، اللَّهُمَّ سَلِّمْ.", "segs": [{"ar": "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ،", "uz": "Kuch-quvvat faqat Allohdandir, Alloh bizga kifoya qiladi,"}, {"ar": "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ، اللَّهُمَّ سَلِّمْ.", "uz": "U qanday ham yaxshi vakildir. Ey Alloh, omon qil."}], "full_uz": "Kuch-quvvat faqat Allohdandir, Alloh bizga kifoya qiladi, U qanday ham yaxshi vakildir. Ey Alloh, omon qil.", "note": null},
{"num": 120, "time": "00:08:12,979 --> 00:08:18,339", "arabic": "أَرَأَيْتَ طُغْيَانًا فَوْقَ هَذَا يَا أَبِي؟", "segs": null, "full_uz": "Bundan ham oshkoraroq zulmni ko'rganmisiz, dadajon?", "note": null},
{"num": 121, "time": "00:08:18,339 --> 00:08:26,159", "arabic": "اللَّهُ الْمُسْتَعَانُ يَا وَلَدِي.", "segs": null, "full_uz": "Yordam faqat Allohdandir, o'g'lim.", "note": null},
{"num": 123, "time": "00:08:26,159 --> 00:08:33,659", "arabic": "هَيَّا قُومُوا حَتَّى لَا تَتَأَخَّرُوا عَنْ صَلَاةِ الْجُمُعَةِ، فَقَدْ كَادَ يُنَادَى لَهَا.", "segs": [{"ar": "هَيَّا قُومُوا حَتَّى لَا تَتَأَخَّرُوا عَنْ صَلَاةِ الْجُمُعَةِ،", "uz": "Yur, turinglar, juma namoziga kechikmanglar,"}, {"ar": "فَقَدْ كَادَ يُنَادَى لَهَا.", "uz": "azon aytilishiga oz qoldi."}], "full_uz": "Yur, turinglar, juma namoziga kechikmanglar, azon aytilishiga oz qoldi.", "note": null},
{"num": 125, "time": "00:08:33,659 --> 00:08:36,259", "arabic": "أَسْتَوْدِعُكَ اللَّهَ يَا أَبِي.", "segs": null, "full_uz": "Sizni Allohga topshiraman, dadajon.", "note": null},
{"num": 126, "time": "00:08:36,259 --> 00:08:39,620", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 128, "time": "00:08:48,340 --> 00:09:08,580", "arabic": "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ، اللَّهُمَّ رُدَّ الْمُسْلِمِينَ إِلَى دِينِهِمْ رَدًّا جَمِيلًا، وَلَا تُؤَاخِذْنَا بِمَا فَعَلَ السُّفَهَاءُ مِنَّا، أَنْتَ حَسْبُنَا وَمَوْلَانَا.", "segs": [{"ar": "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ،", "uz": "Alloh bizga kifoya qiladi,"}, {"ar": "اللَّهُمَّ رُدَّ الْمُسْلِمِينَ إِلَى دِينِهِمْ رَدًّا جَمِيلًا،", "uz": "U qanday ham yaxshi vakildir. Ey Alloh, musulmonlarni o'z dinlariga go'zal qaytarish bilan qaytar,"}, {"ar": "وَلَا تُؤَاخِذْنَا بِمَا فَعَلَ السُّفَهَاءُ مِنَّا،", "uz": "va bizdan bo'lgan nodonlarning qilganlari uchun bizni ushlama. Sen"}, {"ar": "أَنْتَ حَسْبُنَا وَمَوْلَانَا.", "uz": "bizga kifoya qilasan va Xo'jayinimizsan."}], "full_uz": "Alloh bizga kifoya qiladi, U qanday ham yaxshi vakildir. Ey Alloh, musulmonlarni o'z dinlariga go'zal qaytarish bilan qaytar, va bizdan bo'lgan nodonlarning qilganlari uchun bizni ushlama. Sen bizga kifoya qilasan va Xo'jayinimizsan.", "note": null},
{"num": 132, "time": "00:09:18,340 --> 00:09:43,560", "arabic": "أَخْبَرَنِي أَبُوكِ بِذَلِكَ، قَالَ إِنَّهُ ذَهَبَ إِلَى الدُّكَّانِ أَكْثَرَ مِنْ مَرَّةٍ وَلَمْ يَجِدْ زَوْجَكِ هُنَاكَ، لَا أَدْرِي مِنَ الَّذِي ذَهَبَ.", "segs": [{"ar": "أَخْبَرَنِي أَبُوكِ بِذَلِكَ،", "uz": "Otang menga buni aytdi,"}, {"ar": "قَالَ إِنَّهُ ذَهَبَ إِلَى الدُّكَّانِ أَكْثَرَ مِنْ مَرَّةٍ", "uz": "do'konga bir necha marta borib,"}, {"ar": "وَلَمْ يَجِدْ زَوْجَكِ هُنَاكَ،", "uz": "eringni u yerda topmaganini"}, {"ar": "لَا أَدْرِي مِنَ الَّذِي ذَهَبَ.", "uz": "aytdi. Kim borganini bilmayman."}], "full_uz": "Otang menga buni aytdi, do'konga bir necha marta borib, eringni u yerda topmaganini aytdi. Kim borganini bilmayman.", "note": null},
{"num": 137, "time": "00:09:43,559 --> 00:09:52,559", "arabic": "أَتَمْنَعُهُ عِزَّةُ نَفْسِهِ؟ إِذِ الدُّكَّانُ مِلْكُكِ وَلَيْسَ مِلْكَهُ.", "segs": null, "full_uz": "Uni o'z izzat-nafsi to'sib qo'ymoqdami? Axir do'kon sening mulking, uning emas.", "note": null},
{"num": 139, "time": "00:09:52,559 --> 00:09:59,559", "arabic": "عُمَرُ رَجُلٌ يَا أُمِّي وَلَا يُفَكِّرُ بِهَذِهِ الطَّرِيقَةِ، وَلَا فَرْقَ بَيْنَ مَالِي وَمَالِهِ، لَا أَظُنُّ ذَلِكَ.", "segs": [{"ar": "عُمَرُ رَجُلٌ يَا أُمِّي وَلَا يُفَكِّرُ بِهَذِهِ الطَّرِيقَةِ،", "uz": "Umar erkak kishi, onajon, u shunday o'ylamaydi,"}, {"ar": "وَلَا فَرْقَ بَيْنَ مَالِي وَمَالِهِ،", "uz": "mening molim bilan uning moli orasida farq yo'q,"}, {"ar": "لَا أَظُنُّ ذَلِكَ.", "uz": "bunday deb o'ylamayman."}], "full_uz": "Umar erkak kishi, onajon, u shunday o'ylamaydi, mening molim bilan uning moli orasida farq yo'q, bunday deb o'ylamayman.", "note": null},
{"num": 141, "time": "00:09:59,559 --> 00:10:03,239", "arabic": "إِذَنْ مَا السِّرُّ يَا بُنَيَّتِي؟", "segs": null, "full_uz": "Unda sir nima, qizim?", "note": null},
{"num": 142, "time": "00:10:03,239 --> 00:10:09,239", "arabic": "لَعَلَّهُ كَمَا قَالَ عَمِّي أَبُو عُمَيْرٍ، مُتَزَوِّجٌ بِامْرَأَةٍ أُخْرَى.", "segs": null, "full_uz": "Balki amakim Abu Umayr aytganidek, boshqa ayolga uylangandir.", "note": null},
{"num": 144, "time": "00:10:09,240 --> 00:10:14,620", "arabic": "لَا تَفْعَلُوهَا يَا عُمَرُ.", "segs": null, "full_uz": "Buni qilmagin, Umar.", "note": null},
{"num": 145, "time": "00:10:14,620 --> 00:10:22,860", "arabic": "هَلْ عَدَدْتُمُ الْغَدَاءَ؟", "segs": null, "full_uz": "Tushlikni tayyorladinglarmi?", "note": null},
{"num": 146, "time": "00:10:22,860 --> 00:10:23,779", "arabic": "أَجَلْ مَوْلَاتِي.", "segs": null, "full_uz": "Ha, xo'jayinim.", "note": null},
{"num": 147, "time": "00:10:37,779 --> 00:10:42,620", "arabic": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.", "segs": null, "full_uz": "Assalomu alaykum va rahmatullohi va barakatuh.", "note": null},
{"num": 149, "time": "00:10:42,620 --> 00:10:44,519", "arabic": "أَيْنَ عُمَرُ؟", "segs": null, "full_uz": "Umar qayerda?", "note": null},
{"num": 150, "time": "00:10:44,519 --> 00:10:46,220", "arabic": "لِمَ لَمْ يَأْتِ مَعَكَ؟", "segs": null, "full_uz": "Nega u siz bilan kelmadi?", "note": null},
{"num": 151, "time": "00:10:47,200 --> 00:10:50,220", "arabic": "اعْتَذَرَ عَنِ الْمَجِيءِ بِأَنَّ لَدَيْهِ أَمْرًا مُلِحًّا.", "segs": null, "full_uz": "Muhim ishi borligi sababli kelolmasligini bildirdi.", "note": null},
{"num": 152, "time": "00:10:50,860 --> 00:11:13,580", "arabic": "لَا يُسَلِّطَنَّكُمْ عَنْ طَاعَةِ اللَّهِ خَشْيَةُ السُّلْطَانِ، وَلَكُمْ فِي ابْنِ حَنْبَلٍ عِبْرَةٌ، وَلَا تَخْشَوُا النَّاسَ فَاللَّهُ أَحَقُّ أَنْ تَخْشَوْهُ، وَاعْلَمُوا أَنَّ النَّصْرَ مَعَ الصَّبْرِ.", "segs": [{"ar": "لَا يُسَلِّطَنَّكُمْ عَنْ طَاعَةِ اللَّهِ خَشْيَةُ السُّلْطَانِ،", "uz": "Sultondan qo'rqish sizlarni Allohga itoat qilishdan chetlatmasin,"}, {"ar": "وَلَكُمْ فِي ابْنِ حَنْبَلٍ عِبْرَةٌ،", "uz": "sizlarga Ibn Hanbalda ibrat bor. Odamlardan qo'rqmang,"}, {"ar": "وَلَا تَخْشَوُا النَّاسَ فَاللَّهُ أَحَقُّ أَنْ تَخْشَوْهُ،", "uz": "Alloh qo'rqishga eng loyiqroqdir,"}, {"ar": "وَاعْلَمُوا أَنَّ النَّصْرَ مَعَ الصَّبْرِ.", "uz": "va bilib qo'yingki, g'alaba sabr bilan birgadir."}], "full_uz": "Sultondan qo'rqish sizlarni Allohga itoat qilishdan chetlatmasin, sizlarga Ibn Hanbalda ibrat bor. Odamlardan qo'rqmang, Alloh qo'rqishga eng loyiqroqdir, va bilib qo'yingki, g'alaba sabr bilan birgadir.", "note": "Qur'onning \"...ular Allohdan qo'rqadilar va Allohdan boshqa hech kimdan qo'rqmaydilar\" (Ahzob surasi, 39-oyat) mazmuniga yaqin."},
{"num": 157, "time": "00:11:13,580 --> 00:11:29,139", "arabic": "الْحَقُّ يَا إِمَامُ، لَقَدْ كَلَّمْتُ عَشَرَةَ رِجَالٍ فِي الْأَيَّامِ السَّابِقَةِ لِيَنْضَمُّوا إِلَيْنَا، وَلَمْ أَجِدْ حَمَاسًا إِلَّا مِنْ رَجُلٍ وَاحِدٍ، وَهَذَا الْوَاحِدُ هُوَ الْآخَرُ مَا زَالَ مُتَرَدِّدًا فِي أَمْرِهِ.", "segs": [{"ar": "الْحَقُّ يَا إِمَامُ،", "uz": "Rostini aytsam, Imom,"}, {"ar": "لَقَدْ كَلَّمْتُ عَشَرَةَ رِجَالٍ", "uz": "oldingi kunlarda bizga qo'shilishlari"}, {"ar": "فِي الْأَيَّامِ السَّابِقَةِ لِيَنْضَمُّوا إِلَيْنَا،", "uz": "uchun o'nta odam bilan gaplashdim,"}, {"ar": "وَلَمْ أَجِدْ حَمَاسًا إِلَّا مِنْ رَجُلٍ وَاحِدٍ،", "uz": "va faqat bitta odamda shijoat topdim,"}, {"ar": "وَهَذَا الْوَاحِدُ هُوَ الْآخَرُ مَا زَالَ مُتَرَدِّدًا فِي أَمْرِهِ.", "uz": "va u ham hali o'z ishida ikkilanib turibdi."}], "full_uz": "Rostini aytsam, Imom, oldingi kunlarda bizga qo'shilishlari uchun o'nta odam bilan gaplashdim, va faqat bitta odamda shijoat topdim, va u ham hali o'z ishida ikkilanib turibdi.", "note": null},
{"num": 161, "time": "00:11:33,139 --> 00:11:34,639", "arabic": "لَا بَأْسَ.", "segs": null, "full_uz": "Hech gap emas.", "note": null},
{"num": 162, "time": "00:11:34,639 --> 00:12:06,620", "arabic": "نَحْنُ بَيْنَ أَمْرَيْنِ، إِمَّا أَنْ نَدْعُوَ مَنْ نَرَاهُ مُنَاسِبًا لِيَنْضَمَّ إِلَى جَمَاعَتِنَا فَيَكُونَ مَعَنَا فَرْدًا مُحْتَسِبًا يَأْمُرُ بِالْمَعْرُوفِ وَيَنْهَى عَنِ الْمُنْكَرِ، وَبَيْنَ أَلَّا يَرْغَبَ فِي ذَلِكَ فَنَكْتَفِيَ مَعَهُ بِبَيَانِ الْحَقِّ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ، وَفِي الضَّلَالَاتِ الَّتِي يُثِيرُهَا الْمُعْتَزِلَةُ.", "segs": [{"ar": "نَحْنُ بَيْنَ أَمْرَيْنِ، إِمَّا أَنْ نَدْعُوَ مَنْ نَرَاهُ مُنَاسِبًا لِيَنْضَمَّ إِلَى جَمَاعَتِنَا", "uz": "Biz ikki yo'l orasidamiz: yo munosib deb bilgan kishimizni jamoamizga qo'shilishga taklif qilamiz,"}, {"ar": "فَيَكُونَ مَعَنَا فَرْدًا مُحْتَسِبًا يَأْمُرُ بِالْمَعْرُوفِ وَيَنْهَى عَنِ الْمُنْكَرِ،", "uz": "u bizga qo'shilib, yaxshilikka buyuruvchi va yomonlikdan qaytaruvchi bir a'zo bo'ladi,"}, {"ar": "وَبَيْنَ أَلَّا يَرْغَبَ فِي ذَلِكَ فَنَكْتَفِيَ مَعَهُ بِبَيَانِ الْحَقِّ فِي مَسْأَلَةِ خَلْقِ الْقُرْآنِ،", "uz": "yoki u buni xohlamasa, u bilan Qur'onning yaratilganligi masalasida haqni bayon qilish bilan cheklanamiz,"}, {"ar": "وَفِي الضَّلَالَاتِ الَّتِي يُثِيرُهَا الْمُعْتَزِلَةُ.", "uz": "va Mu'tazila ko'targan adashuvlar haqida ham."}], "full_uz": "Biz ikki yo'l orasidamiz: yo munosib deb bilgan kishimizni jamoamizga qo'shilishga taklif qilamiz, u bizga qo'shilib, yaxshilikka buyuruvchi va yomonlikdan qaytaruvchi bir a'zo bo'ladi, yoki u buni xohlamasa, u bilan faqat Qur'onning yaratilganligi masalasi va Mu'tazila ko'targan adashuvlar haqida haqni bayon qilish bilan cheklanamiz.", "note": null},
{"num": 169, "time": "00:12:06,620 --> 00:12:08,860", "arabic": "وَالْحَمْدُ لِلَّهِ.", "segs": null, "full_uz": "Hamd Allohga xosdir.", "note": null},
{"num": 170, "time": "00:12:08,860 --> 00:12:14,179", "arabic": "طَالِبُ بْنُ السِّرَاجِ يَطْلُبُ الْإِذْنَ بِالدُّخُولِ عَلَيْكَ يَا إِمَامُ.", "segs": null, "full_uz": "Tolib ibn as-Siroj sizning huzuringizga kirishga ruxsat so'ryapti, Imom.", "note": null},
{"num": 172, "time": "00:12:14,179 --> 00:12:18,460", "arabic": "إِيَّاكُمْ وَالْحَدِيثَ أَمَامَ ابْنِ السِّرَاجِ.", "segs": null, "full_uz": "Ibn Sirojning oldida gaplashishdan ehtiyot bo'linglar.", "note": null},
{"num": 173, "time": "00:12:18,460 --> 00:12:28,019", "arabic": "أَلَا تَتْرُكُوا بِهِ يَا إِمَامُ؟ إِنَّهُ فَتًى فَطِنٌ وَلَكِنْ فِي النَّفْسِ مِنْهُ شَيْءٌ.", "segs": [{"ar": "أَلَا تَتْرُكُوا بِهِ يَا إِمَامُ؟ إِنَّهُ", "uz": "Unga ishonib qo'ya qolmaysizmi, Imom?"}, {"ar": "فَتًى فَطِنٌ وَلَكِنْ فِي النَّفْسِ مِنْهُ شَيْءٌ.", "uz": "U tetik yigit, lekin ko'ngilda undan bir shubha bor."}], "full_uz": "Unga ishonib qo'ya qolmaysizmi, Imom? U tetik yigit, lekin ko'ngilda undan bir shubha bor.", "note": null},
{"num": 175, "time": "00:12:28,019 --> 00:12:29,820", "arabic": "تَفَضَّلْ تَفَضَّلْ.", "segs": null, "full_uz": "Marhamat, marhamat.", "note": null},
{"num": 176, "time": "00:12:29,820 --> 00:12:35,639", "arabic": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.", "segs": null, "full_uz": "Assalomu alaykum va rahmatullohi va barakatuh.", "note": null},
{"num": 178, "time": "00:12:36,620 --> 00:12:44,860", "arabic": "لَمْ أَرَكَ الْيَوْمَ فِي الصَّلَاةِ، أَحَدَثَ لَكَ مَا تَكْرَهُ لَا قَدَّرَ اللَّهُ؟", "segs": [{"ar": "لَمْ أَرَكَ الْيَوْمَ فِي الصَّلَاةِ،", "uz": "Bugun sizni namozda ko'rmadim,"}, {"ar": "أَحَدَثَ لَكَ مَا تَكْرَهُ لَا قَدَّرَ اللَّهُ؟", "uz": "Alloh saqlasin, sizga yoqmagan biror voqea yuz berdimi?"}], "full_uz": "Bugun sizni namozda ko'rmadim, Alloh saqlasin, sizga yoqmagan biror voqea yuz berdimi?", "note": null},
{"num": 180, "time": "00:12:44,860 --> 00:12:48,600", "arabic": "أَدْرَكَنِي الْوَقْتُ وَأَنَا فِي الْجَانِبِ الْغَرْبِيِّ مِنَ الْمَدِينَةِ فَصَلَّيْتُ هُنَاكَ.", "segs": [{"ar": "أَدْرَكَنِي الْوَقْتُ", "uz": "Vaqt meni shahar"}, {"ar": "وَأَنَا فِي الْجَانِبِ الْغَرْبِيِّ مِنَ الْمَدِينَةِ فَصَلَّيْتُ هُنَاكَ.", "uz": "g'arbiy tomonida topib qoldi, shuning uchun o'sha yerda namoz o'qidim."}], "full_uz": "Vaqt meni shahar g'arbiy tomonida topib qoldi, shuning uchun o'sha yerda namoz o'qidim.", "note": null},
{"num": 181, "time": "00:13:06,620 --> 00:13:08,620", "arabic": "مَنْ بِالْبَابِ؟", "segs": null, "full_uz": "Eshikda kim bor?", "note": null},
{"num": 182, "time": "00:13:08,620 --> 00:13:10,620", "arabic": "أَبُو نَصْرٍ الْخُزَاعِيُّ.", "segs": null, "full_uz": "Abu Nasr al-Xuzoiy.", "note": null},
{"num": 183, "time": "00:13:18,620 --> 00:13:24,620", "arabic": "السَّلَامُ عَلَيْكُمْ يَا أَبَا عَبْدِ اللَّهِ.", "segs": null, "full_uz": "Assalomu alaykum, ey Abu Abdulloh.", "note": null},
{"num": 185, "time": "00:13:25,620 --> 00:13:28,620", "arabic": "أَيُّ رِيحٍ طَيِّبَةٍ سَاقَتْكَ إِلَيْنَا؟", "segs": null, "full_uz": "Qanday xush shabada sizni bizga olib keldi?", "note": null},
{"num": 186, "time": "00:13:29,620 --> 00:13:32,620", "arabic": "أَهْلًا بِنَاصِرِ سُنَّةِ رَسُولِ اللَّهِ.", "segs": null, "full_uz": "Rasululloh sunnatining yordamchisiga marhabo.", "note": null},
{"num": 187, "time": "00:13:32,620 --> 00:13:41,320", "arabic": "قَاتَلَ اللَّهُ مَنْ حَرَمَ الْمُسْلِمِينَ مِنْ إِمَامِهِمْ أَحْمَدَ بْنِ حَنْبَلٍ، غَفَرَ اللَّهُ لَنَا وَلَهُمْ.", "segs": [{"ar": "قَاتَلَ اللَّهُ مَنْ حَرَمَ الْمُسْلِمِينَ مِنْ إِمَامِهِمْ أَحْمَدَ بْنِ حَنْبَلٍ،", "uz": "Alloh musulmonlarni imomlari Ahmad ibn Hanbaldan mahrum qilgan kimsalarni halok qilsin,"}, {"ar": "غَفَرَ اللَّهُ لَنَا وَلَهُمْ.", "uz": "Alloh bizni va ularni mag'firat qilsin."}], "full_uz": "Alloh musulmonlarni imomlari Ahmad ibn Hanbaldan mahrum qilgan kimsalarni halok qilsin, Alloh bizni va ularni mag'firat qilsin.", "note": null},
{"num": 190, "time": "00:13:41,320 --> 00:13:42,279", "arabic": "تَفَضَّلْ.", "segs": null, "full_uz": "Marhamat.", "note": null},
{"num": 191, "time": "00:14:02,620 --> 00:14:11,539", "arabic": "أَمْرٌ عَظِيمٌ يَشْغَلُكَ عَنِّي يَا عُمَرُ.", "segs": null, "full_uz": "Katta bir ish seni mendan chalg'itib qo'yibdi, Umar.", "note": null},
{"num": 193, "time": "00:14:11,539 --> 00:14:16,700", "arabic": "يَبْدُو أَنَّ السِّنِينَ قَدْ فَعَلَتْ فِعْلَهَا فِي قَلْبِكَ، وَنَالَتْ مِنِّي فِيهِ.", "segs": [{"ar": "يَبْدُو أَنَّ السِّنِينَ قَدْ فَعَلَتْ فِعْلَهَا فِي قَلْبِكَ،", "uz": "Ko'rinishidan, yillar sening qalbingga o'z ta'sirini o'tkazgan,"}, {"ar": "وَنَالَتْ مِنِّي فِيهِ.", "uz": "va undan meni kamaytirgan."}], "full_uz": "Ko'rinishidan, yillar sening qalbingga o'z ta'sirini o'tkazgan, va undan meni kamaytirgan.", "note": null},
{"num": 195, "time": "00:14:16,700 --> 00:14:22,179", "arabic": "لَا لَا، لَيْسَ الْأَمْرُ كَمَا تَظُنِّينَ يَا سُعَادُ، الرِّجَالُ دَائِمًا لَا يَقُولُونَ الْحَقِيقَةَ.", "segs": [{"ar": "لَا لَا، لَيْسَ الْأَمْرُ كَمَا تَظُنِّينَ يَا سُعَادُ،", "uz": "Yo'q, yo'q, ish sen o'ylagandek emas, Su'od,"}, {"ar": "الرِّجَالُ دَائِمًا لَا يَقُولُونَ الْحَقِيقَةَ.", "uz": "erkaklar har doim haqiqatni aytmaydilar."}], "full_uz": "Yo'q, yo'q, ish sen o'ylagandek emas, Su'od, erkaklar har doim haqiqatni aytmaydilar.", "note": null},
{"num": 197, "time": "00:14:22,179 --> 00:14:28,919", "arabic": "لَقَدْ عِشْتُ دَهْرًا لَا تُخْفِي عَنِّي شَيْئًا، إِنَّمَا أُخْفِيهِ يَصْعُبُ عَلَيَّ قَوْلُهُ، وَأَخَافُ عَلَيْكِ مِنْهُ.", "segs": [{"ar": "لَقَدْ عِشْتُ دَهْرًا لَا تُخْفِي عَنِّي شَيْئًا،", "uz": "Uzoq umr yashadimki, sen mendan hech narsa yashirmading."}, {"ar": "إِنَّمَا أُخْفِيهِ يَصْعُبُ عَلَيَّ قَوْلُهُ،", "uz": "Yashirayotgan narsamni aytish menga qiyin,"}, {"ar": "وَأَخَافُ عَلَيْكِ مِنْهُ.", "uz": "va undan senga xavotirdaman."}], "full_uz": "Uzoq umr yashadimki, sen mendan hech narsa yashirmading. Yashirayotgan narsamni aytish menga qiyin, va undan senga xavotirdaman.", "note": null},
{"num": 200, "time": "00:14:28,919 --> 00:14:32,639", "arabic": "مَا أَهَمَّكَ أَهَمَّنِي، أَلَسْنَا قَلْبًا وَاحِدًا يَا أَبَا أَحْمَدَ؟", "segs": null, "full_uz": "Seni tashvishlantirgan narsa meni ham tashvishlantiradi, biz bir qalb emasmizmi, ey Abu Ahmad?", "note": null},
{"num": 202, "time": "00:14:32,639 --> 00:14:39,980", "arabic": "بَلَى وَاللَّهِ، وَلَأَنْتِ أَعَزُّ عَلَيَّ مِنْ نَفْسِي، إِذَنْ فَلَا تَكْتُمِينِي سِرًّا أَكُونُ لَكَ سَنَدًا وَعَوْنًا.", "segs": [{"ar": "بَلَى وَاللَّهِ،", "uz": "Albatta, vallohi,"}, {"ar": "وَلَأَنْتِ أَعَزُّ عَلَيَّ مِنْ نَفْسِي،", "uz": "va sen menga o'zimdan ham azizsan."}, {"ar": "إِذَنْ فَلَا تَكْتُمِينِي سِرًّا أَكُونُ لَكَ سَنَدًا وَعَوْنًا.", "uz": "Unda mendan sirni yashirma, senga tayanch va yordamchi bo'lay."}], "full_uz": "Albatta, vallohi, va sen menga o'zimdan ham azizsan. Unda mendan sirni yashirma, senga tayanch va yordamchi bo'lay.", "note": null},
{"num": 204, "time": "00:14:39,980 --> 00:14:46,740", "arabic": "حَسَنًا سَأُخْبِرُكِ بِالْأَمْرِ، وَلَكِنْ إِيَّاكِ أَنْ يَعْلَمَ بِهِ أَحَدٌ.", "segs": null, "full_uz": "Xo'p, senga bu ishni aytaman, lekin buni hech kim bilmasin.", "note": null},
{"num": 206, "time": "00:14:46,740 --> 00:14:49,259", "arabic": "هَاتِ مَا عِنْدَكَ إِنِّي أَسْمَعُكَ.", "segs": null, "full_uz": "Nima bo'lsa ayt, quloq solyapman.", "note": null},
{"num": 207, "time": "00:14:50,059 --> 00:14:58,439", "arabic": "بَلَغَكَ مَا عَزَمْنَا عَلَيْهِ يَا أَبَا عَبْدِ اللَّهِ؟", "segs": null, "full_uz": "Nimaga azm qilganimiz sizga yetib bordimi, ey Abu Abdulloh?", "note": null},
{"num": 209, "time": "00:15:00,259 --> 00:15:10,559", "arabic": "قَدْ بَلَغَنِي أَنَّهُ بَلَغَكَ، جِئْتَ دَاعِيًا أَمْ نَاصِحًا أَمْ مُسْتَنْصِحًا أَمْ مَاذَا؟", "segs": [{"ar": "قَدْ بَلَغَنِي أَنَّهُ بَلَغَكَ،", "uz": "Bu sizga yetganini eshitdim. Da'vatchi bo'lib keldingizmi,"}, {"ar": "جِئْتَ دَاعِيًا أَمْ نَاصِحًا أَمْ مُسْتَنْصِحًا أَمْ مَاذَا؟", "uz": "nasihatchi, maslahat so'rovchi, yoki nima uchun keldingiz?"}], "full_uz": "Bu sizga yetganini eshitdim. Da'vatchi bo'lib keldingizmi, nasihatchi, maslahat so'rovchi, yoki nima uchun keldingiz?", "note": null},
{"num": 211, "time": "00:15:10,559 --> 00:15:14,120", "arabic": "لِنَقُلْ كُلَّ ذَلِكَ يَا إِمَامُ.", "segs": null, "full_uz": "Aytaylikki, hammasi uchun, Imom.", "note": null},
{"num": 212, "time": "00:15:14,120 --> 00:15:27,439", "arabic": "قَدْ فَشَلَ الْأَمْرُ وَتَفَاقَمَ يَا أَبَا عَبْدِ اللَّهِ، وَهَذَا الرَّجُلُ يَفْعَلُ مَا أَنْتَ أَعْلَمُ بِخَطَرِهِ مِنِّي.", "segs": [{"ar": "قَدْ فَشَلَ الْأَمْرُ", "uz": "Ish barbod bo'lib,"}, {"ar": "وَتَفَاقَمَ يَا أَبَا عَبْدِ اللَّهِ،", "uz": "kattalashib ketdi, ey Abu Abdulloh,"}, {"ar": "وَهَذَا الرَّجُلُ يَفْعَلُ مَا أَنْتَ أَعْلَمُ بِخَطَرِهِ مِنِّي.", "uz": "va bu odam qilayotgan ishning xatarini siz mendan yaxshiroq bilasiz."}], "full_uz": "Ish barbod bo'lib, kattalashib ketdi, ey Abu Abdulloh, va bu odam qilayotgan ishning xatarini siz mendan yaxshiroq bilasiz.", "note": null},
{"num": 214, "time": "00:15:27,440 --> 00:15:40,060", "arabic": "أَتَدْرِي أَنَّ أَحْمَدَ بْنَ أَبِي دُؤَادٍ بَدَأَ يَأْمُرُ الْمُعَلِّمِينَ فِي الْكُتَّابِ بِتَعْلِيمِ الصِّبْيَانِ مَسَائِلَهُ الشَّنِيعَةَ وَآرَاءَهُ الضَّالَّةَ؟", "segs": [{"ar": "أَتَدْرِي أَنَّ أَحْمَدَ بْنَ أَبِي دُؤَادٍ بَدَأَ يَأْمُرُ الْمُعَلِّمِينَ فِي الْكُتَّابِ", "uz": "Bilasizmi, Ahmad ibn Abi Du'od maktabdagi o'qituvchilarga buyura boshladi,"}, {"ar": "بِتَعْلِيمِ الصِّبْيَانِ مَسَائِلَهُ الشَّنِيعَةَ وَآرَاءَهُ الضَّالَّةَ؟", "uz": "bolalarni o'zining qabih masalalari va adashgan qarashlari bilan o'qitishni?"}], "full_uz": "Bilasizmi, Ahmad ibn Abi Du'od maktabdagi o'qituvchilarga bolalarni o'zining qabih masalalari va adashgan qarashlari bilan o'qitishni buyura boshladi?", "note": null},
{"num": 217, "time": "00:15:40,060 --> 00:15:43,340", "arabic": "سَمِعْتُ بِذَلِكَ وَأَنْكَرْتُ.", "segs": null, "full_uz": "Buni eshitdim va inkor qildim.", "note": null},
{"num": 218, "time": "00:15:43,340 --> 00:15:46,880", "arabic": "وَكُلُّ ذَلِكَ بِرِضَا الْوَاثِقِ وَرِعَايَتِهِ.", "segs": null, "full_uz": "Va bularning barchasi Vosiqning roziligi va homiyligi bilan.", "note": null},
{"num": 219, "time": "00:15:46,880 --> 00:15:54,600", "arabic": "قَدْ طَفَحَ الْكَيْلُ يَا أَبَا عَبْدِ اللَّهِ، وَلَنْ نَظَلَّ صَامِتِينَ مَقْهُورِينَ أَكْثَرَ مِنْ ذَلِكَ.", "segs": [{"ar": "قَدْ طَفَحَ الْكَيْلُ يَا أَبَا عَبْدِ اللَّهِ،", "uz": "Kosa to'ldi, ey Abu Abdulloh,"}, {"ar": "وَلَنْ نَظَلَّ صَامِتِينَ مَقْهُورِينَ أَكْثَرَ مِنْ ذَلِكَ.", "uz": "biz bundan ortiq sukut saqlab, mazlum bo'lib qolmaymiz."}], "full_uz": "Kosa to'ldi, ey Abu Abdulloh, biz bundan ortiq sukut saqlab, mazlum bo'lib qolmaymiz.", "note": null},
{"num": 221, "time": "00:15:54,600 --> 00:16:05,159", "arabic": "رَأَيْتَ يَا أَبَا نَصْرٍ إِنْ لَمْ تُرَدَّ الْمَفْسَدَةُ إِلَّا بِمَفْسَدَةٍ أَشَدَّ، مَا كُنْتَ تَخْتَارُ؟ لَا تُرَدُّ الْمَفْسَدَةُ بِمَفْسَدَةٍ أَشَدَّ.", "segs": [{"ar": "رَأَيْتَ يَا أَبَا نَصْرٍ إِنْ لَمْ", "uz": "Aytingchi, Abu Nasr,"}, {"ar": "تُرَدَّ الْمَفْسَدَةُ إِلَّا بِمَفْسَدَةٍ أَشَدَّ،", "uz": "agar fasod faqat undan qattiqroq fasod bilan qaytarilsa,"}, {"ar": "مَا كُنْتَ تَخْتَارُ؟ لَا تُرَدُّ الْمَفْسَدَةُ بِمَفْسَدَةٍ أَشَدَّ.", "uz": "nimani tanlagan bo'lardingiz? Fasod undan qattiqroq fasod bilan qaytarilmaydi."}], "full_uz": "Aytingchi, Abu Nasr, agar fasod faqat undan qattiqroq fasod bilan qaytarilsa, nimani tanlagan bo'lardingiz? Fasod undan qattiqroq fasod bilan qaytarilmaydi.", "note": null},
{"num": 225, "time": "00:16:05,159 --> 00:16:15,379", "arabic": "أَخْشَى أَنَّ الْفَسَادَ فِي الْخُرُوجِ عَلَى الْوَاثِقِ بِالسِّلَاحِ أَعْظَمُ مِنَ الْفَسَادِ الْحَاصِلِ بِظُلْمِ هَؤُلَاءِ الْقَوْمِ.", "segs": [{"ar": "أَخْشَى أَنَّ الْفَسَادَ فِي", "uz": "Qo'rqamanki,"}, {"ar": "الْخُرُوجِ عَلَى الْوَاثِقِ بِالسِّلَاحِ", "uz": "Vosiqqa qarshi qurol bilan chiqishdagi fasod bu"}, {"ar": "أَعْظَمُ مِنَ الْفَسَادِ الْحَاصِلِ بِظُلْمِ هَؤُلَاءِ الْقَوْمِ.", "uz": "qavmning zulmidan kelib chiqqan fasoddan kattaroqdir."}], "full_uz": "Qo'rqamanki, Vosiqqa qarshi qurol bilan chiqishdagi fasod bu qavmning zulmidan kelib chiqqan fasoddan kattaroqdir.", "note": null},
{"num": 227, "time": "00:16:15,379 --> 00:16:22,519", "arabic": "صَدَقْتَ وَاللَّهِ يَا أَبَا عَبْدِ اللَّهِ، وَنَحْنُ نَعِي ذَلِكَ كُلَّهُ.", "segs": [{"ar": "صَدَقْتَ وَاللَّهِ يَا أَبَا عَبْدِ اللَّهِ،", "uz": "Vallohi, to'g'ri aytdingiz, ey Abu Abdulloh,"}, {"ar": "وَنَحْنُ نَعِي ذَلِكَ كُلَّهُ.", "uz": "va biz buning barchasini anglaymiz."}], "full_uz": "Vallohi, to'g'ri aytdingiz, ey Abu Abdulloh, va biz buning barchasini anglaymiz.", "note": null},
{"num": 229, "time": "00:16:22,519 --> 00:16:36,240", "arabic": "وَإِنَّمَا قُصَارَى جُهْدِنَا وَمَبْلَغُ جِهَادِنَا أَنْ نَأْمُرَ بِالْمَعْرُوفِ وَنَنْهَى عَنِ الْمُنْكَرِ، دُونَ أَنْ نَسْفِكَ دَمَ مُسْلِمٍ حَرَامًا أَوْ نَجْعَلَهُ عُرْضَةً لِذَلِكَ.", "segs": [{"ar": "وَإِنَّمَا قُصَارَى جُهْدِنَا", "uz": "Bizning eng katta"}, {"ar": "وَمَبْلَغُ جِهَادِنَا أَنْ نَأْمُرَ بِالْمَعْرُوفِ وَنَنْهَى عَنِ الْمُنْكَرِ،", "uz": "harakatimiz va jihodimizning yakuni faqat yaxshilikka buyurish va yomonlikdan qaytarish,"}, {"ar": "دُونَ أَنْ نَسْفِكَ دَمَ مُسْلِمٍ", "uz": "hech bir musulmonning haromi qonini"}, {"ar": "حَرَامًا أَوْ نَجْعَلَهُ عُرْضَةً لِذَلِكَ.", "uz": "to'kmasdan yoki uni bunga duchor qilmasdan."}], "full_uz": "Bizning eng katta harakatimiz va jihodimizning yakuni faqat yaxshilikka buyurish va yomonlikdan qaytarish, hech bir musulmonning haromi qonini to'kmasdan yoki uni bunga duchor qilmasdan.", "note": null},
{"num": 233, "time": "00:16:36,240 --> 00:16:49,620", "arabic": "ذَلِكَ ظَنِّي بِكَ يَا أَبَا نَصْرٍ، فَأَنْتَ قَمِينٌ بِحِفْظِ مَا جَاءَ بِهِ الشَّرْعُ وَالسُّنَّةُ عَنْ سَيِّدِ الْبَشَرِ مُحَمَّدٍ عَلَيْهِ صَلَوَاتُ رَبِّي، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.", "segs": [{"ar": "ذَلِكَ ظَنِّي بِكَ يَا أَبَا نَصْرٍ،", "uz": "Sizga bo'lgan gumonim shu edi, ey Abu Nasr,"}, {"ar": "فَأَنْتَ قَمِينٌ بِحِفْظِ مَا جَاءَ بِهِ الشَّرْعُ", "uz": "siz insonlarning sarvari Muhammad — Robbimning salovatlari unga bo'lsin,"}, {"ar": "وَالسُّنَّةُ عَنْ سَيِّدِ الْبَشَرِ", "uz": "sollallohu alayhi va"}, {"ar": "مُحَمَّدٍ عَلَيْهِ صَلَوَاتُ رَبِّي،", "uz": "sallam — orqali kelgan shariat"}, {"ar": "صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.", "uz": "va sunnatni saqlashga loyiqsiz."}], "full_uz": "Sizga bo'lgan gumonim shu edi, ey Abu Nasr, siz insonlarning sarvari Muhammad — Robbimning salovatlari unga bo'lsin, sollallohu alayhi va sallam — orqali kelgan shariat va sunnatni saqlashga loyiqsiz.", "note": null},
{"num": 237, "time": "00:16:49,620 --> 00:17:12,860", "arabic": "عَلَيْكُمْ بِالْأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ، وَلَا تَخْلَعُوا يَدًا مِنْ طَاعَةٍ، وَلَا تَشُقُّوا عَصَا الْمُسْلِمِينَ، وَلَا تَسْفِكُوا دِمَاءَكُمْ وَدِمَاءَ الْمُسْلِمِينَ مَعَكُمْ، وَانْظُرُوا فِي عَاقِبَةِ أَمْرِكُمْ، وَاصْبِرُوا حَتَّى يَسْتَرِيحَ بَرٌّ أَوْ يُسْتَرَاحَ مِنْ فَاجِرٍ.", "segs": [{"ar": "عَلَيْكُمْ بِالْأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ، وَلَا تَخْلَعُوا يَدًا مِنْ طَاعَةٍ،", "uz": "Yaxshilikka buyurish va yomonlikdan qaytarishni davom ettiringlar, itoatdan qo'l tortmanglar,"}, {"ar": "وَلَا تَشُقُّوا عَصَا الْمُسْلِمِينَ، وَلَا تَسْفِكُوا دِمَاءَكُمْ وَدِمَاءَ الْمُسْلِمِينَ مَعَكُمْ،", "uz": "musulmonlarning yig'ilishini bo'lmanglar, o'z qonlaringiz va musulmonlarning qonini to'kmanglar,"}, {"ar": "وَانْظُرُوا فِي عَاقِبَةِ أَمْرِكُمْ،", "uz": "ishingizning oqibatiga qaranglar,"}, {"ar": "وَاصْبِرُوا حَتَّى يَسْتَرِيحَ بَرٌّ أَوْ يُسْتَرَاحَ مِنْ فَاجِرٍ.", "uz": "va toki yaxshi kishi rohat topguncha yoki yomon kishidan xalos bo'linguncha sabr qilinglar."}], "full_uz": "Yaxshilikka buyurish va yomonlikdan qaytarishni davom ettiringlar, itoatdan qo'l tortmanglar, musulmonlarning yig'ilishini bo'lmanglar, o'z qonlaringiz va siz bilan birga musulmonlarning qonini to'kmanglar, ishingizning oqibatiga qaranglar, va toki yaxshi kishi rohat topguncha yoki yomon kishidan xalos bo'linguncha sabr qilinglar.", "note": "Payg'ambar (sav)ning hokimiyatga qarshi chiqmaslik va sabr haqidagi hadisiga ishora."},
{"num": 245, "time": "00:17:12,860 --> 00:17:36,720", "arabic": "لِذَلِكَ كُلِّهِ رَأَى الْإِمَامُ الْخُزَاعِيُّ أَنَّ سُكُوتَنَا أَكْثَرَ مِنْ ذَلِكَ تَوَاطُؤٌ مِنَّا عَلَى الْمَعْصِيَةِ، وَتَعْطِيلٌ لِوَاجِبِ الْأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ، فَكَانَ الْعَزْمُ عَلَى تَكْوِينِ جَمَاعَةٍ تَأْمُرُ بِالْمَعْرُوفِ وَتَنْهَى عَنِ الْمُنْكَرِ لِتُبَيِّنَ لِلنَّاسِ ضَلَالَ مَا يَدْعُو إِلَيْهِ الْوَاثِقُ وَمَنْ مَعَهُ مِنَ الْمُعْتَزِلَةِ.", "segs": [{"ar": "لِذَلِكَ كُلِّهِ رَأَى الْإِمَامُ الْخُزَاعِيُّ أَنَّ سُكُوتَنَا أَكْثَرَ مِنْ ذَلِكَ تَوَاطُؤٌ مِنَّا عَلَى الْمَعْصِيَةِ،", "uz": "Shularning barchasi uchun Imom al-Xuzoiy bizning bundan ortiq sukutimizni gunohga rozilik deb bildi,"}, {"ar": "وَتَعْطِيلٌ لِوَاجِبِ الْأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ،", "uz": "va yaxshilikka buyurish hamda yomonlikdan qaytarish farzini bajarmaslik deb bildi,"}, {"ar": "فَكَانَ الْعَزْمُ عَلَى تَكْوِينِ جَمَاعَةٍ تَأْمُرُ بِالْمَعْرُوفِ وَتَنْهَى عَنِ الْمُنْكَرِ", "uz": "shuning uchun yaxshilikka buyuradigan va yomonlikdan qaytaradigan bir jamoa tuzishga azm qilindi,"}, {"ar": "لِتُبَيِّنَ لِلنَّاسِ ضَلَالَ مَا يَدْعُو إِلَيْهِ الْوَاثِقُ وَمَنْ مَعَهُ مِنَ الْمُعْتَزِلَةِ.", "uz": "toki odamlarga Vosiq va Mu'tazilaning da'vat qilayotgan adashuvini bayon qilsin."}], "full_uz": "Shularning barchasi uchun Imom al-Xuzoiy bizning bundan ortiq sukutimizni gunohga rozilik va yaxshilikka buyurish hamda yomonlikdan qaytarish farzini bajarmaslik deb bildi, shuning uchun yaxshilikka buyuradigan va yomonlikdan qaytaradigan bir jamoa tuzishga azm qilindi, toki odamlarga Vosiq va u bilan birga bo'lgan Mu'tazilaning da'vat qilayotgan adashuvini bayon qilsin.", "note": null},
{"num": 250, "time": "00:17:36,720 --> 00:17:45,720", "arabic": "هَذَا هُوَ الْأَمْرُ الَّذِي أَخْفَيْتُهُ عَنْكِ، أَعْلَمُ أَنَّهُ أَمْرٌ صَعْبٌ عَلَيْكِ، وَقَدْ سَاءَكِ مَا سَمِعْتِهِ.", "segs": [{"ar": "هَذَا هُوَ الْأَمْرُ الَّذِي أَخْفَيْتُهُ عَنْكِ،", "uz": "Mana bu mendan sendan yashirgan ishim,"}, {"ar": "أَعْلَمُ أَنَّهُ أَمْرٌ صَعْبٌ عَلَيْكِ،", "uz": "bu senga qiyin ish ekanini bilaman,"}, {"ar": "وَقَدْ سَاءَكِ مَا سَمِعْتِهِ.", "uz": "va eshitganing seni xafa qilgandir."}], "full_uz": "Mana bu mendan sendan yashirgan ishim, bu senga qiyin ish ekanini bilaman, va eshitganing seni xafa qilgandir.", "note": null},
{"num": 253, "time": "00:17:45,720 --> 00:17:50,200", "arabic": "وَلَكِنْ... ذَلِكَ ظَنُّكَ يَا أَبَا أَحْمَدَ، لَقَدْ سَرَّنِي مَا سَمِعْتُ.", "segs": [{"ar": "وَلَكِنْ... ذَلِكَ ظَنُّكَ يَا أَبَا أَحْمَدَ،", "uz": "Lekin... bu sizning gumoningiz, ey Abu Ahmad,"}, {"ar": "لَقَدْ سَرَّنِي مَا سَمِعْتُ.", "uz": "eshitganim meni xursand qildi."}], "full_uz": "Lekin... bu sizning gumoningiz, ey Abu Ahmad, eshitganim meni xursand qildi.", "note": null},
{"num": 256, "time": "00:17:50,200 --> 00:17:52,319", "arabic": "وَأَشُدُّ عَلَى يَدِكَ فِيمَا أَقْدَمْتَ.", "segs": null, "full_uz": "Va boshlagan ishingizda sizni qo'llab-quvvatlayman.", "note": null},
{"num": 257, "time": "00:17:52,319 --> 00:17:59,539", "arabic": "أَجَلْ سَرَّنِي، وَسَرَّنِي أَكْثَرَ مِنْ ذَلِكَ أَنْ يَكُونَ زَوْجِي مَشْغُولًا بِدِينِهِ عَنْ دُنْيَاهُ، وَبِآخِرَتِهِ عَنْ حَيَاتِهِ.", "segs": [{"ar": "أَجَلْ سَرَّنِي،", "uz": "Ha, xursand bo'ldim,"}, {"ar": "وَسَرَّنِي أَكْثَرَ مِنْ ذَلِكَ أَنْ يَكُونَ زَوْجِي مَشْغُولًا بِدِينِهِ عَنْ دُنْيَاهُ،", "uz": "va undan ham ko'proq erimning dunyosidan ko'ra dini bilan, hayotidan ko'ra oxirati bilan band"}, {"ar": "وَبِآخِرَتِهِ عَنْ حَيَاتِهِ.", "uz": "bo'lgani meni xursand qildi."}], "full_uz": "Ha, xursand bo'ldim, va undan ham ko'proq erimning dunyosidan ko'ra dini bilan, hayotidan ko'ra oxirati bilan band bo'lgani meni xursand qildi.", "note": null},
{"num": 260, "time": "00:17:59,539 --> 00:18:04,420", "arabic": "وَأَنَا مَعَكَ فِي هَذَا الْأَمْرِ بِقَدْرِ مَا أَسْتَطِيعُ مِنْ طَاعَةِ اللَّهِ وَطَاعَةِ نَبِيِّهِ.", "segs": [{"ar": "وَأَنَا مَعَكَ فِي هَذَا الْأَمْرِ", "uz": "Va men bu ishda siz bilanman,"}, {"ar": "بِقَدْرِ مَا أَسْتَطِيعُ مِنْ طَاعَةِ اللَّهِ وَطَاعَةِ نَبِيِّهِ.", "uz": "Allohga va Uning Payg'ambariga itoat qilishda qo'limdan kelgancha."}], "full_uz": "Va men Allohga va Uning Payg'ambariga itoat qilishda qo'limdan kelgancha bu ishda siz bilanman.", "note": null},
{"num": 262, "time": "00:18:04,420 --> 00:18:07,640", "arabic": "لَوْ تَعْلَمِينَ كَمْ يَسُرُّنِي هَذَا الْكَلَامُ يَا سُعَادُ.", "segs": null, "full_uz": "Bu gaping meni qanchalik xursand qilayotganini bilsang edi, Su'od.", "note": null},
{"num": 263, "time": "00:18:07,640 --> 00:18:24,299", "arabic": "هَلْ تَعْلَمُونَ يَا إِخْوَتِي أَنَّ هَذَا الرَّجُلَ طَغَى وَتَجَبَّرَ؟ هَلْ تَعْلَمُونَ أَنَّ الْمُعْتَزِلَةَ يَسُومُونَ النَّاسَ وَيَجُولُونَ فِي كُلِّ أَرْجَاءِ بَغْدَادَ وَلَا رَادِعَ لَهُمْ؟", "segs": [{"ar": "هَلْ تَعْلَمُونَ يَا إِخْوَتِي", "uz": "Bilasizlarmi, birodarlarim,"}, {"ar": "أَنَّ هَذَا الرَّجُلَ طَغَى", "uz": "bu odam oshkora zulm va zo'ravonlik qildi?"}, {"ar": "وَتَجَبَّرَ؟ هَلْ تَعْلَمُونَ أَنَّ الْمُعْتَزِلَةَ يَسُومُونَ النَّاسَ", "uz": "Bilasizlarmi, Mu'tazila odamlarga azob berib,"}, {"ar": "وَيَجُولُونَ فِي كُلِّ أَرْجَاءِ بَغْدَادَ وَلَا رَادِعَ لَهُمْ؟", "uz": "butun Bag'dod bo'ylab yurishadi va ularga hech kim to'siq bo'la olmaydi?"}], "full_uz": "Bilasizlarmi, birodarlarim, bu odam oshkora zulm va zo'ravonlik qildi? Bilasizlarmi, Mu'tazila odamlarga azob berib, butun Bag'dod bo'ylab yurishadi va ularga hech kim to'siq bo'la olmaydi?", "note": null},
{"num": 268, "time": "00:18:24,299 --> 00:18:37,299", "arabic": "عَلَيْنَا أَنْ نَكُونَ صَفًّا وَاحِدًا، عَلَيْنَا أَنْ نَكُونَ كَلِمَةً وَاحِدَةً فِي وَجْهِ الظُّلْمِ، وَإِلَّا فَطَاعَةٌ لِمَنْ لَا طَاعَةَ لَهُ.", "segs": [{"ar": "عَلَيْنَا أَنْ نَكُونَ صَفًّا وَاحِدًا،", "uz": "Biz bir saf bo'lishimiz kerak,"}, {"ar": "عَلَيْنَا أَنْ نَكُونَ كَلِمَةً وَاحِدَةً فِي وَجْهِ الظُّلْمِ،", "uz": "zulm oldida bir so'z bo'lishimiz kerak,"}, {"ar": "وَإِلَّا فَطَاعَةٌ لِمَنْ لَا طَاعَةَ لَهُ.", "uz": "aks holda itoatga loyiq bo'lmaganga itoat qilgan bo'lamiz."}], "full_uz": "Biz bir saf bo'lishimiz kerak, zulm oldida bir so'z bo'lishimiz kerak, aks holda itoatga loyiq bo'lmaganga itoat qilgan bo'lamiz.", "note": null},
{"num": 274, "time": "00:19:49,220 --> 00:20:26,239", "arabic": "قَدْ قَرَّرْتُ الْعَوْدَةَ إِلَى دَارِي، أَعْلَمُ أَنَّكُمْ تَخَافُونَ عَلَيَّ مِنْ أَمِيرِ الْمُؤْمِنِينَ، وَلَكِنْ بَعْدَ هَذِهِ الْفَتْرَةِ أَدْرَكْتُ بِمَا يُشْبِهُ الْيَقِينَ أَنَّ أَمِيرَ الْمُؤْمِنِينَ لَا يُرِيدُنِي، وَيَكْفِيهِ مِنِّي أَلَّا يَرَانِي، فَقُلْتُ سِيَّانِ إِذَنْ عِنْدَهُ اخْتِفَائِي هُنَا أَوْ فِي دَارِي.", "segs": [{"ar": "قَدْ قَرَّرْتُ الْعَوْدَةَ إِلَى دَارِي، أَعْلَمُ أَنَّكُمْ تَخَافُونَ عَلَيَّ مِنْ أَمِيرِ الْمُؤْمِنِينَ،", "uz": "Uyimga qaytishga qaror qildim. Bilaman, mendan mo'minlar amiri sabab xavotirlanasizlar,"}, {"ar": "وَلَكِنْ بَعْدَ هَذِهِ الْفَتْرَةِ أَدْرَكْتُ بِمَا يُشْبِهُ الْيَقِينَ أَنَّ أَمِيرَ الْمُؤْمِنِينَ لَا يُرِيدُنِي،", "uz": "lekin shu vaqt ichida deyarli aniqlik darajasida angladimki, mo'minlar amiri meni istamaydi,"}, {"ar": "وَيَكْفِيهِ مِنِّي أَلَّا يَرَانِي،", "uz": "unga mendan faqat meni ko'rmaslik yetadi,"}, {"ar": "فَقُلْتُ سِيَّانِ إِذَنْ عِنْدَهُ اخْتِفَائِي هُنَا أَوْ فِي دَارِي.", "uz": "shuning uchun, uning oldida bu yerda yoki uyimda yashirinishim bir xil deb o'yladim."}], "full_uz": "Uyimga qaytishga qaror qildim. Bilaman, mendan mo'minlar amiri sabab xavotirlanasizlar, lekin shu vaqt ichida deyarli aniqlik darajasida angladimki, mo'minlar amiri meni istamaydi, unga mendan faqat meni ko'rmaslik yetadi. Shuning uchun, uning oldida bu yerda yoki uyimda yashirinishim bir xil deb o'yladim.", "note": null},
{"num": 281, "time": "00:20:26,239 --> 00:20:30,519", "arabic": "مَا رَأْيُكَ يَا ابْنَ هَانِئٍ؟", "segs": null, "full_uz": "Fikringiz qanday, Ibn Hani?", "note": null},
{"num": 282, "time": "00:20:30,519 --> 00:20:31,659", "arabic": "الرَّأْيُ مَا تَرَاهُ.", "segs": null, "full_uz": "Fikr siz ko'rgan narsadir.", "note": null},
{"num": 283, "time": "00:20:31,659 --> 00:20:42,779", "arabic": "وَلَكِنِّي أَرَى أَنَّ رُجُوعَكَ إِلَى بَيْتِكَ رُبَّمَا أَثَارَ حَفِيظَةَ الْمُعْتَزِلَةِ وَأَشْيَاعِهِمْ، فَيُؤَلِّبُونَ عَلَيْكَ أَمِيرَ الْمُؤْمِنِينَ.", "segs": [{"ar": "وَلَكِنِّي أَرَى أَنَّ رُجُوعَكَ إِلَى بَيْتِكَ رُبَّمَا أَثَارَ حَفِيظَةَ الْمُعْتَزِلَةِ وَأَشْيَاعِهِمْ،", "uz": "Lekin men uyingizga qaytishingiz balki Mu'tazila va ularning izdoshlarining g'ashini keltirishini o'ylayman,"}, {"ar": "فَيُؤَلِّبُونَ عَلَيْكَ أَمِيرَ الْمُؤْمِنِينَ.", "uz": "va mo'minlar amirini sizga qarshi qo'zg'atishlarini."}], "full_uz": "Lekin men uyingizga qaytishingiz balki Mu'tazila va ularning izdoshlarining g'ashini keltirib, mo'minlar amirini sizga qarshi qo'zg'atishlarini o'ylayman.", "note": null},
{"num": 286, "time": "00:20:42,779 --> 00:20:48,000", "arabic": "وَأَنْتَ يَا أَبَا بَكْرٍ؟", "segs": null, "full_uz": "Sen-chi, Abu Bakr?", "note": null},
{"num": 287, "time": "00:20:48,000 --> 00:20:57,240", "arabic": "أَتَّفِقُ مَعَ أَبِي إِسْحَاقَ، وَلَا رَأْيَ بَعْدَ رَأْيِكَ يَا إِمَامُ، عَلَيْكَ الْقَوْلُ وَعَلَيْنَا الْقَبُولُ وَالْإِذْعَانُ.", "segs": [{"ar": "أَتَّفِقُ مَعَ أَبِي إِسْحَاقَ،", "uz": "Abu Ishoq bilan roziman,"}, {"ar": "وَلَا رَأْيَ بَعْدَ رَأْيِكَ يَا إِمَامُ،", "uz": "va sizning fikringizdan keyin boshqa fikr yo'q, Imom,"}, {"ar": "عَلَيْكَ الْقَوْلُ وَعَلَيْنَا الْقَبُولُ وَالْإِذْعَانُ.", "uz": "gap sizga, qabul va bo'ysunish esa bizga."}], "full_uz": "Abu Ishoq bilan roziman, va sizning fikringizdan keyin boshqa fikr yo'q, Imom, gap sizga, qabul va bo'ysunish esa bizga.", "note": null},
{"num": 290, "time": "00:20:57,240 --> 00:21:18,799", "arabic": "إِنْ بَقِيتَ هُنَا تَظَلُّ قُلُوبُنَا مُمَزَّقَةً لِابْتِعَادِكَ عَنْهَا، وَإِنْ عُدْتَ لِلْبَيْتِ تَمَزَّقَتْ قُلُوبُنَا بِقُرْبِكَ خَوْفًا عَلَيْكَ، وَفِي الْحَالَيْنِ نَحْنُ عَلَى جَمْرِ التَّرَقُّبِ يَا أَبِي، فَامْضِ مُرْتَاحَةً لَهُ نَفْسُكَ وَهَدَاكَ إِلَيْهِ رَبُّكَ.", "segs": [{"ar": "إِنْ بَقِيتَ هُنَا تَظَلُّ قُلُوبُنَا مُمَزَّقَةً لِابْتِعَادِكَ عَنْهَا،", "uz": "Agar shu yerda qolsangiz, sizdan uzoqligimiz uchun qalblarimiz parchalanaveradi,"}, {"ar": "وَإِنْ عُدْتَ لِلْبَيْتِ تَمَزَّقَتْ قُلُوبُنَا بِقُرْبِكَ خَوْفًا عَلَيْكَ،", "uz": "agar uyga qaytsangiz, sizga xavotir bilan yaqinligimizdan qalblarimiz parchalanadi,"}, {"ar": "وَفِي الْحَالَيْنِ نَحْنُ عَلَى جَمْرِ التَّرَقُّبِ يَا أَبِي،", "uz": "ikkala holatda ham biz kutish cho'g'ida turibmiz, dadajon,"}, {"ar": "فَامْضِ مُرْتَاحَةً لَهُ نَفْسُكَ وَهَدَاكَ إِلَيْهِ رَبُّكَ.", "uz": "nafsingiz xotirjam bo'lgan yo'lga boring, va Robbingiz sizni shunga hidoyat qilsin."}], "full_uz": "Agar shu yerda qolsangiz, sizdan uzoqligimiz uchun qalblarimiz parchalanaveradi, agar uyga qaytsangiz, sizga xavotir bilan yaqinligimizdan qalblarimiz parchalanadi. Ikkala holatda ham biz kutish cho'g'ida turibmiz, dadajon. Nafsingiz xotirjam bo'lgan yo'lga boring, va Robbingiz sizni shunga hidoyat qilsin.", "note": null},
{"num": 296, "time": "00:21:18,799 --> 00:21:26,480", "arabic": "أَلَدَى أَحَدِكُمْ رَأْيٌ غَيْرُهُ؟", "segs": null, "full_uz": "Sizlardan birortangizda boshqa fikr bormi?", "note": null},
{"num": 297, "time": "00:21:26,480 --> 00:21:28,279", "arabic": "لَا رَأْيَ بَعْدَ رَأْيِكَ يَا إِمَامُ.", "segs": null, "full_uz": "Sizning fikringizdan keyin boshqa fikr yo'q, Imom.", "note": null},
{"num": 298, "time": "00:21:28,279 --> 00:21:33,259", "arabic": "إِذَنْ عَلَى بَرَكَةِ اللَّهِ.", "segs": null, "full_uz": "Unda Allohning barakoti bilan.", "note": null},
{"num": 299, "time": "00:21:37,339 --> 00:21:41,939", "arabic": "الْعِلْمُ مَوْلَايَ أَنَّ ابْنَ حَنْبَلٍ مُخْتَفٍ فِي دَارِهِ.", "segs": null, "full_uz": "Ma'lumki, xo'jayinim, Ibn Hanbal o'z uyida yashiringan.", "note": null},
{"num": 300, "time": "00:21:41,940 --> 00:21:47,480", "arabic": "مَوْلَاكَ يَعْلَمُ كُلَّ الْبُيُوتِ الَّتِي اخْتَفَى فِيهَا أَحْمَدُ بْنُ حَنْبَلٍ.", "segs": [{"ar": "مَوْلَاكَ يَعْلَمُ كُلَّ الْبُيُوتِ الَّتِي", "uz": "Xo'jayining Ahmad ibn Hanbal"}, {"ar": "اخْتَفَى فِيهَا أَحْمَدُ بْنُ حَنْبَلٍ.", "uz": "yashiringan barcha uylarni biladi."}], "full_uz": "Xo'jayining Ahmad ibn Hanbal yashiringan barcha uylarni biladi.", "note": null},
{"num": 301, "time": "00:21:47,480 --> 00:21:51,720", "arabic": "إِذَنْ فَقَدْ صَفَحَ عَنْهُ مَوْلَايَ.", "segs": null, "full_uz": "Unda xo'jayinim uni kechirgan ekan-da.", "note": null},
{"num": 302, "time": "00:21:51,720 --> 00:21:55,259", "arabic": "أَتُرِيدُنِي أَنْ أَصْفَحَ عَنْ رَجُلٍ ظَالِمٍ مِثْلِهِ؟", "segs": null, "full_uz": "Mendan unga o'xshash zolim odamni kechirishimni istaysanmi?", "note": null},
{"num": 303, "time": "00:21:55,259 --> 00:21:59,900", "arabic": "وَلَكِنَّهُ مُحَصَّنٌ بِعِنَادِهِ وَحُبِّ الْغَوْغَاءِ لَهُ.", "segs": null, "full_uz": "Lekin u o'z qaysarligi va olomonning unga bo'lgan muhabbati bilan mustahkamlangan.", "note": null},
{"num": 304, "time": "00:21:59,900 --> 00:22:19,079", "arabic": "وَأَنْتَ تَعْلَمُ لَوْ فَعَلْنَا بِهِ مَا فَعَلْنَاهُ سَابِقًا لَجَعَلْنَا مِنْهُ أُسْطُورَةً بَيْنَ الْعَوَامِّ، فَأَيُّهُمَا أَفْضَلُ أَنْ يَظَلَّ فِي بَيْتِهِ لَا يَرَاهُ النَّاسُ، أَوْ نَسْجُنَهُ أَوْ نَقْتُلَهُ فَنَجْعَلَ بِذَلِكَ ذِكْرَهُ عَلَى كُلِّ لِسَانٍ وَنَزِيدَ مِنْ تَعَلُّقِ الْعَوَامِّ بِهِ؟", "segs": [{"ar": "وَأَنْتَ تَعْلَمُ لَوْ فَعَلْنَا بِهِ مَا فَعَلْنَاهُ سَابِقًا لَجَعَلْنَا مِنْهُ أُسْطُورَةً بَيْنَ الْعَوَامِّ،", "uz": "Va bilasanki, agar unga ilgari qilganimizni yana qilsak, uni omma orasida afsonaga aylantirgan bo'lardik,"}, {"ar": "فَأَيُّهُمَا أَفْضَلُ أَنْ يَظَلَّ فِي بَيْتِهِ لَا يَرَاهُ النَّاسُ،", "uz": "xo'sh, qaysi biri yaxshiroq — uning uyida qolib, odamlar uni ko'rmasligimi,"}, {"ar": "أَوْ نَسْجُنَهُ أَوْ نَقْتُلَهُ فَنَجْعَلَ بِذَلِكَ ذِكْرَهُ عَلَى كُلِّ لِسَانٍ", "uz": "yoki uni qamash yoki o'ldirish orqali uning nomini har bir tilga tushirishmi,"}, {"ar": "وَنَزِيدَ مِنْ تَعَلُّقِ الْعَوَامِّ بِهِ؟", "uz": "va ommaning unga bog'lanishini yanada kuchaytirishmi?"}], "full_uz": "Va bilasanki, agar unga ilgari qilganimizni yana qilsak, uni omma orasida afsonaga aylantirgan bo'lardik. Xo'sh, qaysi biri yaxshiroq — uning uyida qolib, odamlar uni ko'rmasligimi, yoki uni qamash yoki o'ldirish orqali uning nomini har bir tilga tushirib, ommaning unga bog'lanishini yanada kuchaytirishmi?", "note": null},
{"num": 310, "time": "00:22:19,079 --> 00:22:27,160", "arabic": "مَوْلَايَ أَمِيرُ الْمُؤْمِنِينَ لَا يَقُولُ إِلَّا الْحَقَّ.", "segs": null, "full_uz": "Xo'jayinim, mo'minlar amiri faqat haqni aytadi.", "note": null},
{"num": 312, "time": "00:22:27,160 --> 00:22:40,919", "arabic": "إِنْ قُتِلَ ابْنُ حَنْبَلٍ فَذَلِكَ إِحْيَاءٌ لِبِدْعَتِهِ وَنَشْرٌ لِضَلَالَتِهِ، وَالْعَامَّةُ تَفْتِنُهَا قِصَصُ الْبُطُولَاتِ، وَخَاصَّةً قِصَصُ أَهْلِ الْبِدَعِ وَالضَّلَالَاتِ.", "segs": [{"ar": "إِنْ قُتِلَ ابْنُ حَنْبَلٍ فَذَلِكَ إِحْيَاءٌ لِبِدْعَتِهِ وَنَشْرٌ لِضَلَالَتِهِ،", "uz": "Agar Ibn Hanbal o'ldirilsa, bu uning bid'atini tiriltirish va adashuvini tarqatishdir. Ommani esa qahramonlik hikoyalari,"}, {"ar": "وَالْعَامَّةُ تَفْتِنُهَا قِصَصُ الْبُطُولَاتِ،", "uz": "ayniqsa bid'at"}, {"ar": "وَخَاصَّةً قِصَصُ أَهْلِ الْبِدَعِ وَالضَّلَالَاتِ.", "uz": "va adashuv ahlining hikoyalari o'ziga tortadi."}], "full_uz": "Agar Ibn Hanbal o'ldirilsa, bu uning bid'atini tiriltirish va adashuvini tarqatishdir. Ommani esa qahramonlik hikoyalari, ayniqsa bid'at va adashuv ahlining hikoyalari o'ziga tortadi.", "note": null},
{"num": 316, "time": "00:22:40,919 --> 00:22:46,679", "arabic": "دَعُوهُ فِي بَيْتِهِ حَتَّى يَمُوتَ ذِكْرُهُ أَوْ يَمُوتَ بَدَلَهُ.", "segs": null, "full_uz": "Uni o'z uyida qoldiringlar, toki uning nomi o'lsin, yoki u o'zi o'lsin.", "note": null},
{"num": 317, "time": "00:22:46,679 --> 00:22:55,220", "arabic": "الْمُسْلِمُونَ فِي صَلَاةِ الْجُمُعَةِ، وَأَبُوكَ مَعَ الْخَوَالِفِ يَا عَبْدَ اللَّهِ.", "segs": [{"ar": "الْمُسْلِمُونَ فِي صَلَاةِ الْجُمُعَةِ،", "uz": "Musulmonlar juma namozida,"}, {"ar": "وَأَبُوكَ مَعَ الْخَوَالِفِ يَا عَبْدَ اللَّهِ.", "uz": "otang esa qolganlar bilan uyda, Abdulloh."}], "full_uz": "Musulmonlar juma namozida, otang esa qolganlar bilan uyda, Abdulloh.", "note": null},
{"num": 319, "time": "00:22:55,220 --> 00:23:03,619", "arabic": "أَرْجُو أَنْ لَا تَرَى تَعَسًا كَالَّذِي رَآهُ أَبُوكَ، بِحِرْمَانِهِ مِنَ الْجُمُعَةِ وَالْجَمَاعَاتِ.", "segs": [{"ar": "أَرْجُو أَنْ لَا تَرَى تَعَسًا كَالَّذِي رَآهُ أَبُوكَ،", "uz": "Umid qilamanki, sen otang ko'rgan kabi jumadan va jamoatlardan"}, {"ar": "بِحِرْمَانِهِ مِنَ الْجُمُعَةِ وَالْجَمَاعَاتِ.", "uz": "mahrum bo'lgan mashaqqatni ko'rmaysan."}], "full_uz": "Umid qilamanki, sen otang ko'rgan kabi jumadan va jamoatlardan mahrum bo'lgan mashaqqatni ko'rmaysan.", "note": null},
{"num": 321, "time": "00:23:03,619 --> 00:23:16,579", "arabic": "وَفَّقَكَ اللَّهُ يَا وَلَدِي، وَأَبْعَدَ عَنْكَ الْمَصَائِبَ، وَحَبَّبَ اللَّهُ إِلَيْكَ الْعِلْمَ بِكِتَابِهِ وَسُنَّةِ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.", "segs": [{"ar": "وَفَّقَكَ اللَّهُ يَا وَلَدِي،", "uz": "Alloh senga muvaffaqiyat bersin, o'g'lim,"}, {"ar": "وَأَبْعَدَ عَنْكَ الْمَصَائِبَ،", "uz": "va sendan balolarni uzoqlashtirsin,"}, {"ar": "وَحَبَّبَ اللَّهُ إِلَيْكَ الْعِلْمَ بِكِتَابِهِ وَسُنَّةِ رَسُولِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.", "uz": "va Alloh Kitobi va Rasuli (sollallohu alayhi va sallam)ning sunnati bilan ilmni senga sevimli qilsin."}], "full_uz": "Alloh senga muvaffaqiyat bersin, o'g'lim, va sendan balolarni uzoqlashtirsin, va Alloh Kitobi va Rasuli (sollallohu alayhi va sallam)ning sunnati bilan ilmni senga sevimli qilsin.", "note": null},
{"num": 325, "time": "00:23:16,579 --> 00:23:20,799", "arabic": "اللَّهُ الْمُسْتَعَانُ.", "segs": null, "full_uz": "Yordam faqat Allohdandir.", "note": null},
{"num": 326, "time": "00:23:33,619 --> 00:23:50,039", "arabic": "بِالْأَمْسِ انْتَهَيْنَا يَا عَبْدَ اللَّهِ مِنْ حِفْظِ جُزْءِ الْخَامِسِ وَالْعِشْرِينَ مِنَ الْقُرْآنِ الْكَرِيمِ، الْآنَ تُعِيدُهُ عَلَيَّ حِفْظًا حَتَّى نَبْدَأَ بِجُزْءِ السَّادِسِ وَالْعِشْرِينَ، ابْدَأْ مِنْ سُورَةِ الشُّورَى.", "segs": [{"ar": "بِالْأَمْسِ انْتَهَيْنَا يَا عَبْدَ", "uz": "Kecha, Abdulloh,"}, {"ar": "اللَّهِ مِنْ حِفْظِ جُزْءِ الْخَامِسِ", "uz": "Qur'oni Karimning yigirma beshinchi juzini yodlashni"}, {"ar": "وَالْعِشْرِينَ مِنَ الْقُرْآنِ الْكَرِيمِ،", "uz": "tugatgan edik. Endi yigirma"}, {"ar": "الْآنَ تُعِيدُهُ عَلَيَّ حِفْظًا حَتَّى نَبْدَأَ بِجُزْءِ السَّادِسِ وَالْعِشْرِينَ،", "uz": "oltinchi juzni boshlashimizdan oldin uni menga yoddan qaytar."}, {"ar": "ابْدَأْ مِنْ سُورَةِ الشُّورَى.", "uz": "Shuro surasidan boshla."}], "full_uz": "Kecha, Abdulloh, Qur'oni Karimning yigirma beshinchi juzini yodlashni tugatgan edik. Endi yigirma oltinchi juzni boshlashimizdan oldin uni menga yoddan qaytar. Shuro surasidan boshla.", "note": null},
{"num": 329, "time": "00:24:03,619 --> 00:24:06,519", "arabic": "الْفَضْلُ لِلَّهِ أَوَّلًا وَأَخِيرًا.", "segs": null, "full_uz": "Fazl avvalu oxir Allohnikidir.", "note": null},
{"num": 330, "time": "00:24:06,519 --> 00:24:08,899", "arabic": "السَّلَامُ عَلَيْكُمْ.", "segs": null, "full_uz": "Assalomu alaykum.", "note": null},
{"num": 331, "time": "00:24:08,899 --> 00:24:11,419", "arabic": "اللَّهُ أَكْبَرُ.", "segs": null, "full_uz": "Allohu akbar.", "note": null},
{"num": 332, "time": "00:24:11,419 --> 00:24:13,959", "arabic": "مَا وَرَاءَكَ يَا طَالِبُ؟", "segs": null, "full_uz": "Ortingda nima xabar bor, Tolib?", "note": null},
{"num": 333, "time": "00:24:13,959 --> 00:24:15,179", "arabic": "أَمْرٌ جَلَلٌ يَا إِمَامُ.", "segs": null, "full_uz": "Katta bir voqea, Imom.", "note": null},
{"num": 334, "time": "00:24:15,179 --> 00:24:18,919", "arabic": "خَيْرٌ لَنَا وَشَرٌّ لِأَعْدَائِنَا يَا ابْنَ السِّرَاجِ.", "segs": null, "full_uz": "Bizga yaxshilik, dushmanlarimizga yomonlik bo'lsin, Ibn Siroj.", "note": null},
{"num": 335, "time": "00:24:18,919 --> 00:24:22,899", "arabic": "وَمِنْ أَيْنَ يَأْتِي الْخَيْرُ وَسَيْفُ الطُّغَاةِ عَلَى رِقَابِنَا؟", "segs": null, "full_uz": "Zolimlarning qilichi bo'ynimizda turgan ekan, yaxshilik qayerdan keladi?", "note": null},
{"num": 336, "time": "00:24:22,899 --> 00:24:31,019", "arabic": "لَقَدْ تُوُفِّيَ الْيَوْمَ فِي سِجْنِ الْوَاثِقِ الْإِمَامُ أَبُو يَعْقُوبَ الْبُوَيْطِيُّ، صَاحِبُ الْإِمَامِ الشَّافِعِيِّ الَّذِي جَاءَ بِهِ مِنْ مِصْرَ لِكَيْ يُقِرَّ بِخَلْقِ الْقُرْآنِ.", "segs": [{"ar": "لَقَدْ تُوُفِّيَ الْيَوْمَ فِي سِجْنِ الْوَاثِقِ الْإِمَامُ أَبُو يَعْقُوبَ الْبُوَيْطِيُّ،", "uz": "Bugun Vosiqning qamog'ida Imom Abu Ya'qub al-Buvaytiy vafot etdi,"}, {"ar": "صَاحِبُ الْإِمَامِ الشَّافِعِيِّ الَّذِي جَاءَ بِهِ مِنْ مِصْرَ لِكَيْ يُقِرَّ بِخَلْقِ الْقُرْآنِ.", "uz": "u Imom Shofi'iyning safdoshi bo'lib, Qur'onning yaratilganligini tan olsin deb Misrdan olib kelingan edi."}], "full_uz": "Bugun Vosiqning qamog'ida Imom Abu Ya'qub al-Buvaytiy, Imom Shofi'iyning safdoshi, Qur'onning yaratilganligini tan olsin deb Misrdan olib kelingan kishi, vafot etdi.", "note": null},
{"num": 340, "time": "00:24:31,019 --> 00:24:34,220", "arabic": "مَاذَا؟", "segs": null, "full_uz": "Nima?", "note": null},
{"num": 341, "time": "00:24:34,220 --> 00:24:37,639", "arabic": "أَجَلْ، وَقَدْ دَفَنَهُ الْجُنْدُ خِفْيَةً عَنِ النَّاسِ هَذَا الْمَسَاءَ.", "segs": null, "full_uz": "Ha, va soldatlar uni bugun kechqurun odamlardan yashirincha dafn qilishdi.", "note": null},
{"num": 342, "time": "00:24:37,639 --> 00:24:45,279", "arabic": "اللَّهُ أَكْبَرُ، لَقَدْ حَقَّ الْقَوْلُ عَلَى عَدُوِّ اللَّهِ الْقَاتِلِ لِلْعُلَمَاءِ وَالشُّيُوخِ، لَمْ يَعُدْ لَنَا عُذْرٌ فِي الصَّبْرِ عَلَى مَنِ اسْتَبَاحَ الدِّمَاءَ.", "segs": [{"ar": "اللَّهُ أَكْبَرُ،", "uz": "Allohu akbar,"}, {"ar": "لَقَدْ حَقَّ الْقَوْلُ عَلَى عَدُوِّ اللَّهِ الْقَاتِلِ لِلْعُلَمَاءِ وَالشُّيُوخِ،", "uz": "olimlar va shayxlarni o'ldiruvchi Allohning dushmani ustidan so'z haq"}, {"ar": "لَمْ يَعُدْ لَنَا عُذْرٌ فِي", "uz": "bo'ldi. Qonlarni halol sanagan kimsaga"}, {"ar": "الصَّبْرِ عَلَى مَنِ اسْتَبَاحَ الدِّمَاءَ.", "uz": "sabr qilishga endi bahonamiz yo'q."}], "full_uz": "Allohu akbar, olimlar va shayxlarni o'ldiruvchi Allohning dushmani ustidan so'z haq bo'ldi. Qonlarni halol sanagan kimsaga sabr qilishga endi bahonamiz yo'q.", "note": null},
{"num": 344, "time": "00:24:45,279 --> 00:24:48,660", "arabic": "اللَّهُ أَكْبَرُ.", "segs": null, "full_uz": "Allohu akbar.", "note": null},
{"num": 347, "time": "00:24:48,660 --> 00:24:53,559", "arabic": "عَلَى رِسْلِكُمْ يَا قَوْمُ، لِنَفْهَمَ الْأَمْرَ أَوَّلًا.", "segs": null, "full_uz": "Shoshilmanglar, qavm, avval ishni tushunib olaylik.", "note": null},
{"num": 349, "time": "00:24:53,559 --> 00:25:04,480", "arabic": "إِنَّنَا نَعِي أَسَالِيبَ الطُّغَاةِ يَا إِمَامُ، فَعَدُوُّ اللَّهِ الْوَاثِقُ وَزَبَانِيَتُهُ دَفَنُوا أَبَا يَعْقُوبَ الْبُوَيْطِيَّ فِي جُنْحِ اللَّيْلِ، وَلَا أَحَدَ يَعْلَمُ كَيْفَ لَقِيَ حَتْفَهُ.", "segs": [{"ar": "إِنَّنَا نَعِي أَسَالِيبَ الطُّغَاةِ يَا إِمَامُ،", "uz": "Biz zolimlarning usullarini anglaymiz, Imom,"}, {"ar": "فَعَدُوُّ اللَّهِ الْوَاثِقُ", "uz": "Allohning dushmani Vosiq va uning"}, {"ar": "وَزَبَانِيَتُهُ دَفَنُوا أَبَا يَعْقُوبَ الْبُوَيْطِيَّ فِي جُنْحِ اللَّيْلِ،", "uz": "jallodlari Abu Ya'qub al-Buvaytiyni tun qorong'usida dafn qilishdi,"}, {"ar": "وَلَا أَحَدَ يَعْلَمُ كَيْفَ لَقِيَ حَتْفَهُ.", "uz": "va uning qanday halok bo'lganini hech kim bilmaydi."}], "full_uz": "Biz zolimlarning usullarini anglaymiz, Imom, Allohning dushmani Vosiq va uning jallodlari Abu Ya'qub al-Buvaytiyni tun qorong'usida dafn qilishdi, va uning qanday halok bo'lganini hech kim bilmaydi.", "note": null},
{"num": 354, "time": "00:25:04,480 --> 00:25:08,279", "arabic": "قَاتِلُهُ مَنْ وَضَعَهُ فِي السِّجْنِ مُنْذُ سِنِينَ.", "segs": null, "full_uz": "Uni o'ldirgan kishi — uni yillar avval qamoqqa tashlagan kimsadir.", "note": null},
{"num": 355, "time": "00:25:08,279 --> 00:25:28,720", "arabic": "رَحْمَةُ اللَّهِ عَلَيْكَ أَيُّهَا الْبُوَيْطِيُّ، رَحْمَةُ اللَّهِ عَلَيْكَ يَا صَاحِبَ الشَّافِعِيِّ وَحَامِلَ عِلْمِهِ، لَقَدْ بَذَلْتَ رُوحَكَ وَلَمْ تَنْطِقْ كَلِمَةَ الضَّلَالَةِ.", "segs": [{"ar": "رَحْمَةُ اللَّهِ عَلَيْكَ أَيُّهَا الْبُوَيْطِيُّ،", "uz": "Allohning rahmati senga bo'lsin, ey Buvaytiy,"}, {"ar": "رَحْمَةُ اللَّهِ عَلَيْكَ يَا صَاحِبَ الشَّافِعِيِّ وَحَامِلَ عِلْمِهِ،", "uz": "Allohning rahmati senga bo'lsin, ey Shofi'iyning safdoshi va uning ilmini ko'targan kishi,"}, {"ar": "لَقَدْ بَذَلْتَ رُوحَكَ وَلَمْ تَنْطِقْ كَلِمَةَ الضَّلَالَةِ.", "uz": "sen jonungni fido qilding-u, adashuv so'zini aytmading."}], "full_uz": "Allohning rahmati senga bo'lsin, ey Buvaytiy, Allohning rahmati senga bo'lsin, ey Shofi'iyning safdoshi va uning ilmini ko'targan kishi. Sen jonungni fido qilding-u, adashuv so'zini aytmading.", "note": null},
{"num": 360, "time": "00:25:30,720 --> 00:25:50,720", "arabic": "أَرْجُو أَنْ تَكُونَ مِمَّنْ قَالَ فِيهِمُ اللَّهُ تَعَالَى: مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ، فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُ وَمَا بَدَّلُوا تَبْدِيلًا.", "segs": [{"ar": "أَرْجُو أَنْ تَكُونَ مِمَّنْ", "uz": "Umid qilamanki,"}, {"ar": "قَالَ فِيهِمُ اللَّهُ تَعَالَى:", "uz": "siz Alloh taolo haqingizda: \"Mo'minlar orasida Allohga bergan"}, {"ar": "مِنَ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ،", "uz": "ahdlariga sodiq qolgan erlar bor, ulardan ba'zilari ajalini topdi,"}, {"ar": "فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ", "uz": "ba'zilari esa kutmoqda,"}, {"ar": "وَمِنْهُمْ مَنْ يَنْتَظِرُ وَمَا بَدَّلُوا تَبْدِيلًا.", "uz": "va ular hech qanday o'zgarish qilmadilar\" degan kishilardan bo'lasiz."}], "full_uz": "Umid qilamanki, siz Alloh taolo haqingizda: \"Mo'minlar orasida Allohga bergan ahdlariga sodiq qolgan erlar bor, ulardan ba'zilari ajalini topdi, ba'zilari esa kutmoqda, va ular hech qanday o'zgarish qilmadilar\" degan kishilardan bo'lasiz.", "note": "Qur'on, Ahzob surasi, 23-oyat."},
{"num": 364, "time": "00:25:51,720 --> 00:26:08,779", "arabic": "وَمَا تَرَى يَا أَبَا نَصْرٍ؟ أَيَّ بُغْضٍ لِأَمِيرِ الْمُؤْمِنِينَ كُنْتُمْ تَكْتُمُونَهُ عَنِّي؟ كَانَ يَجِبُ أَنْ يَمُوتَ الْبُوَيْطِيُّ مُنْذُ دَهْرٍ حَتَّى تَفْقِدُوا حَذَرَكُمْ أَمَامِي وَتَكْشِفُوا خَبِيئَةَ قُلُوبِكُمُ النَّجِسَةِ، وَيْلٌ لَكُمْ بِمَا كَسَبَتْ أَيْدِيكُمْ.", "segs": [{"ar": "وَمَا تَرَى يَا أَبَا نَصْرٍ؟ أَيَّ بُغْضٍ لِأَمِيرِ الْمُؤْمِنِينَ كُنْتُمْ تَكْتُمُونَهُ عَنِّي؟", "uz": "Xo'sh, nima deysiz, Abu Nasr? Mo'minlar amiriga qanday nafratni mendan yashirib kelayapsizlar?"}, {"ar": "كَانَ يَجِبُ أَنْ يَمُوتَ الْبُوَيْطِيُّ مُنْذُ دَهْرٍ", "uz": "Buvaytiy anchadan beri o'lishi kerak edi,"}, {"ar": "حَتَّى تَفْقِدُوا حَذَرَكُمْ أَمَامِي وَتَكْشِفُوا خَبِيئَةَ قُلُوبِكُمُ النَّجِسَةِ،", "uz": "toki mening oldimda ehtiyotkorligingizni yo'qotib, najis qalblaringizning sirini ochib qo'yasizlar,"}, {"ar": "وَيْلٌ لَكُمْ بِمَا كَسَبَتْ أَيْدِيكُمْ.", "uz": "qo'llaringiz qozongan narsa uchun voy holingizga."}], "full_uz": "Xo'sh, nima deysiz, Abu Nasr? Mo'minlar amiriga qanday nafratni mendan yashirib kelayapsizlar? Buvaytiy anchadan beri o'lishi kerak edi, toki mening oldimda ehtiyotkorligingizni yo'qotib, najis qalblaringizning sirini ochib qo'yasizlar. Qo'llaringiz qozongan narsa uchun voy holingizga.", "note": null},
{"num": 369, "time": "00:26:08,779 --> 00:26:18,539", "arabic": "الْأَخْبَارُ فِي الْخَارِجِ لَيْسَتْ كَمَا نُحِبُّ يَا أَبِي، وَمَتَى نَرْجُوهَا كَذَلِكَ وَالشَّيْطَانُ فِي الْقَصْرِ يَفْتِنُ؟", "segs": [{"ar": "الْأَخْبَارُ فِي الْخَارِجِ لَيْسَتْ", "uz": "Tashqaridagi xabarlar biz istagandek emas,"}, {"ar": "كَمَا نُحِبُّ يَا أَبِي،", "uz": "dadajon, va saroyda shayton fitna qo'zg'atib turgan ekan,"}, {"ar": "وَمَتَى نَرْجُوهَا كَذَلِكَ وَالشَّيْطَانُ فِي الْقَصْرِ يَفْتِنُ؟", "uz": "qachon undan yaxshisini kutamiz?"}], "full_uz": "Tashqaridagi xabarlar biz istagandek emas, dadajon, va saroyda shayton fitna qo'zg'atib turgan ekan, qachon undan yaxshisini kutamiz?", "note": null},
{"num": 371, "time": "00:26:18,539 --> 00:26:22,900", "arabic": "مَا الَّذِي يَحْدُثُ فِي الْخَارِجِ يَا صَالِحُ؟", "segs": null, "full_uz": "Tashqarida nima bo'lyapti, Solih?", "note": null},
{"num": 372, "time": "00:26:22,900 --> 00:26:29,599", "arabic": "النَّاسُ حَانِقُونَ مِنْ قَبْلُ، وَقَدْ زَادَهُمْ خَبَرُ وَفَاةِ الْبُوَيْطِيِّ فِي سِجْنِ الْخَلِيفَةِ حَنَقًا.", "segs": [{"ar": "النَّاسُ حَانِقُونَ مِنْ قَبْلُ،", "uz": "Odamlar allaqachon g'azablangan,"}, {"ar": "وَقَدْ زَادَهُمْ خَبَرُ وَفَاةِ الْبُوَيْطِيِّ فِي سِجْنِ الْخَلِيفَةِ حَنَقًا.", "uz": "va xalifaning qamog'ida Buvaytiyning vafot etgani haqidagi xabar ularning g'azabini yanada oshirdi."}], "full_uz": "Odamlar allaqachon g'azablangan, va xalifaning qamog'ida Buvaytiyning vafot etgani haqidagi xabar ularning g'azabini yanada oshirdi.", "note": null},
{"num": 374, "time": "00:26:29,599 --> 00:26:33,339", "arabic": "أَخْشَى أَنْ لَا نَسْلَمَ مِنْهَا هَذِهِ الْمَرَّةَ يَا أَبِي.", "segs": null, "full_uz": "Qo'rqamanki, bu safar undan omon qolmaymiz, dadajon.", "note": null},
{"num": 375, "time": "00:26:33,339 --> 00:26:36,899", "arabic": "اللَّهُمَّ سَلِّمْ.", "segs": null, "full_uz": "Ey Alloh, omon qil.", "note": null},
{"num": 376, "time": "00:26:36,899 --> 00:26:39,799", "arabic": "مَا الَّذِي نَنْتَظِرُهُ الْآنَ؟", "segs": null, "full_uz": "Endi nimani kutyapmiz?", "note": null},
{"num": 377, "time": "00:26:40,500 --> 00:26:48,799", "arabic": "نَنْتَظِرُ أَوَامِرَ أَمِيرِ الْمُؤْمِنِينَ حَفِظَهُ اللَّهُ وَأَبْقَاهُ.", "segs": null, "full_uz": "Mo'minlar amirining (Alloh uni asrasin va saqlasin) buyrug'ini kutyapmiz.", "note": null},
{"num": 379, "time": "00:26:50,319 --> 00:26:58,240", "arabic": "أَخَافُ أَنْ يَشْعُرَ هَذَا الْخُزَاعِيُّ بِالْخَطَرِ فَيَهْرُبَ قَبْلَ أَنْ تَأْتِيَنَا أَوَامِرُ أَمِيرِ الْمُؤْمِنِينَ حَفِظَهُ اللَّهُ وَأَبْقَاهُ.", "segs": [{"ar": "أَخَافُ أَنْ يَشْعُرَ هَذَا الْخُزَاعِيُّ بِالْخَطَرِ فَيَهْرُبَ", "uz": "Qo'rqamanki, bu al-Xuzoiy xavfni sezib qochib ketadi,"}, {"ar": "قَبْلَ أَنْ تَأْتِيَنَا أَوَامِرُ أَمِيرِ الْمُؤْمِنِينَ حَفِظَهُ اللَّهُ وَأَبْقَاهُ.", "uz": "mo'minlar amirining (Alloh uni asrasin) buyrug'i bizga yetib kelmasdan oldin."}], "full_uz": "Qo'rqamanki, bu al-Xuzoiy xavfni sezib, mo'minlar amirining buyrug'i bizga yetib kelmasdan qochib ketishi mumkin.", "note": null},
{"num": 382, "time": "00:27:00,539 --> 00:27:09,200", "arabic": "مِنْ مَأْمَنِهِ يُؤْتَى الْحَذِرُ أَيُّهَا الْأَرْمَنِيُّ، فَلَا تَقْلَقْ.", "segs": null, "full_uz": "Ehtiyotkor odam ko'pincha o'zini xavfsiz deb bilgan joyidan yetib olinadi, ey Armaniy, xavotir olma.", "note": "\"من مأمنه يؤتى الحذر\" — hatto ehtiyotkor bo'lsa ham inson o'zi xavfsiz deb bilgan joyidan zarar ko'rishi mumkinligi haqidagi arab maqoli."},
{"num": 384, "time": "00:27:09,200 --> 00:27:16,000", "arabic": "أَخْشَى يَا مَوْلَايَ أَنَّ كَلَامَ الْأَمِيرِ أَبِي عَبْدِ اللَّهِ الْأَرْمَنِيِّ لَمْ يُجَانِبِ الصَّوَابَ.", "segs": [{"ar": "أَخْشَى يَا مَوْلَايَ أَنَّ كَلَامَ الْأَمِيرِ", "uz": "Qo'rqamanki, xo'jayinim,"}, {"ar": "أَبِي عَبْدِ اللَّهِ الْأَرْمَنِيِّ لَمْ يُجَانِبِ الصَّوَابَ.", "uz": "amir Abu Abdulloh al-Armaniyning gapi to'g'ridan uzoq emas."}], "full_uz": "Qo'rqamanki, xo'jayinim, amir Abu Abdulloh al-Armaniyning gapi to'g'ridan uzoq emas.", "note": null},
{"num": 386, "time": "00:27:16,000 --> 00:27:18,500", "arabic": "كَيْفَ؟", "segs": null, "full_uz": "Qanday?", "note": null},
{"num": 387, "time": "00:27:18,500 --> 00:27:25,560", "arabic": "الْخُزَاعِيُّ هُوَ مَنْ كَانَ يُدِيرُ تِلْكَ الْفِئَاتِ الَّتِي كَانَتْ تَحْشُو عُقُولَ الْعَوَامِّ بِكُرْهِنَا وَتُثِيرُهَا فِي السِّرِّ عَلَيْنَا.", "segs": [{"ar": "الْخُزَاعِيُّ هُوَ مَنْ كَانَ يُدِيرُ تِلْكَ", "uz": "Al-Xuzoiy — omma xalqining ongini bizga bo'lgan nafrat bilan to'ldirib,"}, {"ar": "الْفِئَاتِ الَّتِي كَانَتْ تَحْشُو عُقُولَ الْعَوَامِّ بِكُرْهِنَا", "uz": "ularni bizga qarshi maxfiy ravishda qo'zg'atgan"}, {"ar": "وَتُثِيرُهَا فِي السِّرِّ عَلَيْنَا.", "uz": "o'sha guruhlarni boshqargan kishi edi."}], "full_uz": "Al-Xuzoiy — omma xalqining ongini bizga bo'lgan nafrat bilan to'ldirib, ularni bizga qarshi maxfiy ravishda qo'zg'atgan o'sha guruhlarni boshqargan kishi edi.", "note": null},
{"num": 390, "time": "00:27:25,560 --> 00:27:28,660", "arabic": "أَخْبَارٌ أَكِيدَةٌ؟", "segs": null, "full_uz": "Aniq xabarmi?", "note": null},
{"num": 391, "time": "00:27:29,300 --> 00:27:30,800", "arabic": "كَمُثُولِي أَمَامَكُمُ الْآنَ.", "segs": null, "full_uz": "Hozir sizning oldingizda turganimdek aniq.", "note": null},
{"num": 392, "time": "00:27:30,800 --> 00:27:35,940", "arabic": "إِذَنْ فَقَدْ هَرْوَلَ إِلَى الْمَوْتِ بِقَدَمَيْنِ.", "segs": null, "full_uz": "Unda u o'limga o'z oyoqlari bilan yugurib boribdi.", "note": null},
{"num": 393, "time": "00:27:35,940 --> 00:27:39,660", "arabic": "وَلَكِنْ بِأَيِّ ذَرِيعَةٍ نَتَخَلَّصُ مِنْهُ؟", "segs": null, "full_uz": "Lekin qanday bahona bilan undan qutulamiz?", "note": null},
{"num": 394, "time": "00:27:41,580 --> 00:27:44,380", "arabic": "بِاتِّهَامِهِ بِإِفْسَادِ عُقُولِ النَّاسِ.", "segs": null, "full_uz": "Odamlarning ongini buzganlikda uni ayblab.", "note": null},
{"num": 395, "time": "00:27:44,380 --> 00:27:55,660", "arabic": "مُسَوِّغٌ غَيْرُ كَافٍ، وَلَا يَرْقَى لِحَمْلِ أَمِيرِ الْمُؤْمِنِينَ عَلَى التَّخَلُّصِ مِنْهُ.", "segs": [{"ar": "مُسَوِّغٌ غَيْرُ كَافٍ،", "uz": "Bu yetarli asos emas,"}, {"ar": "وَلَا يَرْقَى لِحَمْلِ أَمِيرِ الْمُؤْمِنِينَ عَلَى التَّخَلُّصِ مِنْهُ.", "uz": "va mo'minlar amirini undan qutulishga undash uchun yetarli darajaga yetmaydi."}], "full_uz": "Bu yetarli asos emas, va mo'minlar amirini undan qutulishga undash uchun yetarli darajaga yetmaydi.", "note": null},
{"num": 398, "time": "00:27:56,740 --> 00:27:57,740", "arabic": "وَإِذَنْ؟", "segs": null, "full_uz": "Xo'sh?", "note": null},
{"num": 399, "time": "00:28:04,540 --> 00:28:10,620", "arabic": "لَا تَقْلَقُوا، وَادَعُوا هَذَا الْأَمْرَ لِي.", "segs": null, "full_uz": "Xavotir olmanglar, bu ishni menga qoldiring.", "note": null},
{"num": 401, "time": "00:28:13,380 --> 00:28:54,860", "arabic": "اللَّهُمَّ أَخْلِصْ نِيَّتِي، وَاجْعَلِ اعْتِمَادِي عَلَيْكَ وَثِقَتِي بِكَ، وَاجْعَلْنِي مِنْ عِبَادِكَ الصَّالِحِينَ الْمُصْلِحِينَ، الْعَالِمِينَ الْعَامِلِينَ، الْآمِرِينَ بِالْمَعْرُوفِ وَالنَّاهِينَ عَنِ الْمُنْكَرِ، السَّاعِينَ بِتَوْفِيقِكَ لِنُصْرَةِ الْأُمَّةِ وَالدِّينِ، اللَّهُمَّ كَفِّنِي شَرَّ نَفْسِي وَشَرَّ عَدُوِّي وَعَدُوِّكَ.", "segs": [{"ar": "اللَّهُمَّ أَخْلِصْ نِيَّتِي، وَاجْعَلِ اعْتِمَادِي عَلَيْكَ وَثِقَتِي بِكَ،", "uz": "Ey Alloh, niyatimni xolis qil, tayanchim va ishonchimni Senga qil,"}, {"ar": "وَاجْعَلْنِي مِنْ عِبَادِكَ الصَّالِحِينَ الْمُصْلِحِينَ، الْعَالِمِينَ الْعَامِلِينَ،", "uz": "va meni Sening solih va isloh qiluvchi, biluvchi va amal qiluvchi bandalaringdan qil,"}, {"ar": "الْآمِرِينَ بِالْمَعْرُوفِ وَالنَّاهِينَ عَنِ الْمُنْكَرِ، السَّاعِينَ بِتَوْفِيقِكَ لِنُصْرَةِ الْأُمَّةِ وَالدِّينِ،", "uz": "yaxshilikka buyuruvchi va yomonlikdan qaytaruvchi, Sening muvaffaqiyating bilan ummat va din uchun harakat qiluvchilardan qil,"}, {"ar": "اللَّهُمَّ كَفِّنِي شَرَّ نَفْسِي وَشَرَّ عَدُوِّي وَعَدُوِّكَ.", "uz": "ey Alloh, meni o'z nafsimning yomonligidan hamda dushmanim va Sening dushmaningning yomonligidan asra."}], "full_uz": "Ey Alloh, niyatimni xolis qil, tayanchim va ishonchimni Senga qil, va meni Sening solih va isloh qiluvchi bandalaringdan, biluvchi va amal qiluvchilardan, yaxshilikka buyuruvchi va yomonlikdan qaytaruvchilardan, Sening muvaffaqiyating bilan ummat va din uchun harakat qiluvchilardan qil. Ey Alloh, meni o'z nafsimning yomonligidan hamda dushmanim va Sening dushmaningning yomonligidan asra.", "note": null},
{"num": 408, "time": "00:28:54,860 --> 00:28:59,820", "arabic": "اللَّهُمَّ آمِينَ.", "segs": null, "full_uz": "Ey Alloh, omin.", "note": null},
{"num": 409, "time": "00:28:59,820 --> 00:29:06,620", "arabic": "السَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ وَصَحْبِهِ.", "segs": null, "full_uz": "Mo'minlar amiriga va uning sheriklariga salom bo'lsin.", "note": null},
{"num": 410, "time": "00:29:06,620 --> 00:29:09,300", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.", "segs": null, "full_uz": "Va alaykum assalomu va rahmatullohi va barakatuh.", "note": null},
{"num": 411, "time": "00:29:15,660 --> 00:29:25,980", "arabic": "يَبْدُو أَنَّ رِجَالَكَ يُغَطُّونَ فِي النَّوْمِ، وَاللُّصُوصُ يَسْتَبِيحُونَ حُصُونَ الْخِلَافَةِ.", "segs": [{"ar": "يَبْدُو أَنَّ رِجَالَكَ يُغَطُّونَ فِي النَّوْمِ،", "uz": "Ko'rinishidan, sening odamlaring uyquga g'arq bo'lib yotishibdi,"}, {"ar": "وَاللُّصُوصُ يَسْتَبِيحُونَ حُصُونَ الْخِلَافَةِ.", "uz": "o'g'rilar esa xalifalikning qal'alarini halol sanashyapti."}], "full_uz": "Ko'rinishidan, sening odamlaring uyquga g'arq bo'lib yotishibdi, o'g'rilar esa xalifalikning qal'alarini halol sanashyapti.", "note": null},
{"num": 413, "time": "00:29:25,980 --> 00:29:34,000", "arabic": "رِجَالِي رِجَالُ أَمِيرِ الْمُؤْمِنِينَ، يَعْرِفُهُمْ وَيَعْرِفُ حِرْصَهُمْ وَوَلَاءَهُمْ لِمَوْلَايَ حَفِظَهُ اللَّهُ.", "segs": [{"ar": "رِجَالِي رِجَالُ أَمِيرِ الْمُؤْمِنِينَ،", "uz": "Mening odamlarim mo'minlar amirining odamlaridir,"}, {"ar": "يَعْرِفُهُمْ وَيَعْرِفُ حِرْصَهُمْ وَوَلَاءَهُمْ لِمَوْلَايَ حَفِظَهُ اللَّهُ.", "uz": "u ularni va ularning xo'jayinimga (Alloh uni asrasin) bo'lgan g'ayrati va sadoqatini biladi."}], "full_uz": "Mening odamlarim mo'minlar amirining odamlaridir, u ularni va ularning xo'jayinimga (Alloh uni asrasin) bo'lgan g'ayrati va sadoqatini biladi.", "note": null},
{"num": 416, "time": "00:29:34,000 --> 00:29:38,200", "arabic": "إِذَنْ فَتَعْسًا لِأَمِيرِ الْمُؤْمِنِينَ عَلَى رِجَالٍ كَهَؤُلَاءِ.", "segs": null, "full_uz": "Unda mo'minlar amiriga bunday odamlar uchun halokat bo'lsin.", "note": null},
{"num": 417, "time": "00:29:38,200 --> 00:29:43,060", "arabic": "فِي ذَاتِ نَفْسِي أَمِيرَ الْمُؤْمِنِينَ.", "segs": null, "full_uz": "Ichimda o'ylaymanki, mo'minlar amiri.", "note": null},
{"num": 418, "time": "00:29:43,060 --> 00:29:45,000", "arabic": "مَا الْأَمْرُ؟", "segs": null, "full_uz": "Nima gap?", "note": null},
{"num": 419, "time": "00:29:45,660 --> 00:29:58,340", "arabic": "اسْمَعْ إِذَنْ مَقَالَةَ هَذَا الرَّجُلِ، كَيْ تَعْرِفَ مَدَى تَخَاذُلِ رِجَالِكَ الَّذِينَ لَا تَشُكُّ فِي حِرْصِهِمْ وَوَلَائِهِمْ.", "segs": [{"ar": "اسْمَعْ إِذَنْ مَقَالَةَ هَذَا الرَّجُلِ،", "uz": "Unda bu odamning gapini eshit,"}, {"ar": "كَيْ تَعْرِفَ مَدَى تَخَاذُلِ رِجَالِكَ الَّذِينَ لَا تَشُكُّ فِي حِرْصِهِمْ وَوَلَائِهِمْ.", "uz": "toki g'ayrati va sadoqatidan shubhalanmagan odamlaringning naqadar loqaydligini bilib ol."}], "full_uz": "Unda bu odamning gapini eshit, toki g'ayrati va sadoqatidan shubhalanmagan odamlaringning naqadar loqaydligini bilib ol.", "note": null},
{"num": 421, "time": "00:29:58,340 --> 00:30:00,759", "arabic": "تَكَلَّمْ أَيُّهَا الرَّجُلُ.", "segs": null, "full_uz": "Gapir, odam bola.", "note": null},
{"num": 422, "time": "00:30:00,759 --> 00:30:04,960", "arabic": "أَسْمِعُوا الطَّاعَةَ يَا مَوْلَايَ، كُلُّ مَا فِي الْأَمْرِ...", "segs": null, "full_uz": "Itoat qilamiz, xo'jayinim, gap shundaki...", "note": null},
{"num": 426, "time": "00:31:15,660 --> 00:31:35,000", "arabic": "وَأَمِيرُ الْمُؤْمِنِينَ مَكَانَةُ أَهْلِكَ عِنْدَهُ، تِلْكَ الْمَكَانَةُ الَّتِي لَمْ تَرْعَهَا حَقَّ رِعَايَتِهَا، كَيْفَ كَانَ جَدُّكَ مِنْ نُقَبَاءِ بَنِي الْعَبَّاسِ، وَتَصِيرُ أَنْتَ مَارِقًا عَلَى أَمِيرِ الْمُؤْمِنِينَ، نَاكِثًا بَيْعَةَ إِمَامِكَ؟", "segs": [{"ar": "وَأَمِيرُ الْمُؤْمِنِينَ مَكَانَةُ أَهْلِكَ عِنْدَهُ، تِلْكَ الْمَكَانَةُ الَّتِي لَمْ تَرْعَهَا حَقَّ رِعَايَتِهَا،", "uz": "Mo'minlar amirining oldida oilangning mavqei bor, o'sha mavqeni haqli tarzda saqlamading,"}, {"ar": "كَيْفَ كَانَ جَدُّكَ مِنْ نُقَبَاءِ بَنِي الْعَبَّاسِ،", "uz": "buvang Bani Abbosning noiblaridan bo'lgan bo'lsa,"}, {"ar": "وَتَصِيرُ أَنْتَ مَارِقًا عَلَى أَمِيرِ الْمُؤْمِنِينَ،", "uz": "sen esa mo'minlar amiriga qarshi isyonchi bo'lib qolyapsan,"}, {"ar": "نَاكِثًا بَيْعَةَ إِمَامِكَ؟", "uz": "imomingga bergan bay'atingni buzuvchi bo'lib?"}], "full_uz": "Va mo'minlar amirining oldida oilangning mavqei bor, o'sha mavqeni haqli tarzda saqlamading. Buvang Bani Abbosning noiblaridan bo'lgan bo'lsa, sen esa mo'minlar amiriga qarshi isyonchi, imomingga bergan bay'atingni buzuvchi bo'lib qolyapsanmi?", "note": null},
{"num": 434, "time": "00:31:35,000 --> 00:31:37,560", "arabic": "لَمْ أَنْكُثْ لِلْإِمَامِ بَيْعَةً.", "segs": null, "full_uz": "Imomga bergan bay'atimni buzmadim.", "note": null},
{"num": 435, "time": "00:31:37,560 --> 00:31:43,600", "arabic": "إِنَّمَا مَنْ نَكَثَ الْعُهُودَ وَخَانَ الْأَمَانَةَ هُوَ مَنْ سَاقَكَ إِلَى هُنَا.", "segs": [{"ar": "إِنَّمَا مَنْ نَكَثَ الْعُهُودَ", "uz": "Ahdlarni buzib,"}, {"ar": "وَخَانَ الْأَمَانَةَ هُوَ مَنْ سَاقَكَ إِلَى هُنَا.", "uz": "omonatga xiyonat qilgan kishi — seni bu yerga olib kelgan kishidir."}], "full_uz": "Ahdlarni buzib, omonatga xiyonat qilgan kishi — seni bu yerga olib kelgan kishidir.", "note": null},
{"num": 437, "time": "00:31:43,600 --> 00:31:44,420", "arabic": "يَا ابْنَ مُصْعَبٍ.", "segs": null, "full_uz": "Ey Ibn Mus'ab.", "note": null},
{"num": 438, "time": "00:31:44,420 --> 00:31:52,440", "arabic": "أَلَمْ تَتَعَلَّمْ وَتَعْلَمْ أَنَّ النُّصْحَ لِوَلِيِّ الْأَمْرِ مِنَ الدِّينِ؟", "segs": null, "full_uz": "Rahbarga nasihat qilish dindan ekanini o'rganmaganmiding va bilmasmiding?", "note": "\"الدين النصيحة\" — Payg'ambar (sav)ning mashhur hadisiga ishora (Sahih Muslim)."},
{"num": 439, "time": "00:31:52,440 --> 00:32:01,620", "arabic": "تُرِيدُ أَنْ تَخْرُجَ بِسَيْفِكَ عَلَى الْإِمَامِ، وَتَقْتُلَ الْمُسْلِمِينَ وَتَفْتِنَهُمْ عَنْ دِينِهِمْ؟", "segs": [{"ar": "تُرِيدُ أَنْ تَخْرُجَ بِسَيْفِكَ عَلَى الْإِمَامِ،", "uz": "Qilichingiz bilan imomga qarshi chiqib,"}, {"ar": "وَتَقْتُلَ الْمُسْلِمِينَ وَتَفْتِنَهُمْ عَنْ دِينِهِمْ؟", "uz": "musulmonlarni o'ldirib, ularni dinlaridan chalg'itmoqchimisiz?"}], "full_uz": "Qilichingiz bilan imomga qarshi chiqib, musulmonlarni o'ldirib, ularni dinlaridan chalg'itmoqchimisiz?", "note": null},
{"num": 441, "time": "00:32:01,620 --> 00:32:08,080", "arabic": "قَاتَلَ اللَّهُ مَنْ حَمَلَ عَلَى الْمُسْلِمِينَ سَيْفًا أَوْ كَانَ لِلْفِتْنَةِ سَبَبًا.", "segs": [{"ar": "قَاتَلَ اللَّهُ مَنْ حَمَلَ عَلَى الْمُسْلِمِينَ", "uz": "Alloh musulmonlarga qarshi qilich ko'targan yoki fitnaga"}, {"ar": "سَيْفًا أَوْ كَانَ لِلْفِتْنَةِ سَبَبًا.", "uz": "sabab bo'lgan kishini halok qilsin."}], "full_uz": "Alloh musulmonlarga qarshi qilich ko'targan yoki fitnaga sabab bo'lgan kishini halok qilsin.", "note": null},
{"num": 444, "time": "00:32:38,079 --> 00:32:38,659", "arabic": "هَيَّا.", "segs": null, "full_uz": "Yuring.", "note": null},
{"num": 445, "time": "00:32:38,659 --> 00:32:52,599", "arabic": "نُرِيدُ عُمَرَ بْنَ عَامِرٍ الْإِسْكَافِيَّ.", "segs": null, "full_uz": "Bizga Umar ibn Omir al-Iskofiy kerak.", "note": null},
{"num": 447, "time": "00:32:52,599 --> 00:33:01,799", "arabic": "لَا تُؤْذُوا أَحَدًا مِنْ أَهْلِ الْبَيْتِ، نُرِيدُ عُمَرَ بْنَ عَامِرٍ الْإِسْكَافِيَّ فَقَطْ.", "segs": [{"ar": "لَا تُؤْذُوا أَحَدًا مِنْ أَهْلِ الْبَيْتِ،", "uz": "Uy ahlidan hech kimga ozor bermanglar,"}, {"ar": "نُرِيدُ عُمَرَ بْنَ عَامِرٍ الْإِسْكَافِيَّ فَقَطْ.", "uz": "bizga faqat Umar ibn Omir al-Iskofiy kerak."}], "full_uz": "Uy ahlidan hech kimga ozor bermanglar, bizga faqat Umar ibn Omir al-Iskofiy kerak.", "note": null},
{"num": 449, "time": "00:33:01,799 --> 00:33:12,379", "arabic": "هَيَّا فَتِّشُوا الْبَيْتَ بِسُرْعَةٍ.", "segs": null, "full_uz": "Yuring, uyni tezda tekshiring.", "note": null},
{"num": 451, "time": "00:33:38,079 --> 00:33:53,559", "arabic": "جُنْدُ أَمِيرِ الْمُؤْمِنِينَ قَبَضُوا عَلَى الْخُزَاعِيِّ وَجَمَاعَتِهِ.", "segs": null, "full_uz": "Mo'minlar amirining askarlari al-Xuzoiy va uning jamoasini qo'lga olishdi.", "note": null},
{"num": 452, "time": "00:33:53,559 --> 00:33:54,399", "arabic": "مَتَى؟", "segs": null, "full_uz": "Qachon?", "note": null},
{"num": 453, "time": "00:33:54,399 --> 00:33:58,359", "arabic": "مُنْذُ الْأَمْسِ وَهُمْ يَجُولُونَ فِي الْأَزِقَّةِ وَيَتَصَيَّدُونَهُمْ وَاحِدًا تِلْوَ الْآخَرِ يَا أَبِي.", "segs": [{"ar": "مُنْذُ الْأَمْسِ وَهُمْ يَجُولُونَ فِي الْأَزِقَّةِ", "uz": "Kechadan beri ko'chalarda yurib,"}, {"ar": "وَيَتَصَيَّدُونَهُمْ وَاحِدًا تِلْوَ الْآخَرِ يَا أَبِي.", "uz": "ularni birin-ketin ovlashyapti, dadajon."}], "full_uz": "Kechadan beri ko'chalarda yurib, ularni birin-ketin ovlashyapti, dadajon.", "note": null},
{"num": 454, "time": "00:33:58,359 --> 00:34:07,960", "arabic": "اللَّهُمَّ أَلْطِفْ بِعِبَادِكَ الصَّالِحِينَ النَّاصِحِينَ، وَرُدَّ عَنْهُمْ كَيْدَ الظَّالِمِينَ، آمِينَ يَا رَبِّ.", "segs": [{"ar": "اللَّهُمَّ أَلْطِفْ بِعِبَادِكَ الصَّالِحِينَ النَّاصِحِينَ،", "uz": "Ey Alloh, solih va nasihatgo'y bandalaringga marhamat qil,"}, {"ar": "وَرُدَّ عَنْهُمْ كَيْدَ الظَّالِمِينَ، آمِينَ يَا رَبِّ.", "uz": "va zolimlarning hiylasini ulardan qaytar. Omin, ey Robbim."}], "full_uz": "Ey Alloh, solih va nasihatgo'y bandalaringga marhamat qil, va zolimlarning hiylasini ulardan qaytar. Omin, ey Robbim.", "note": null},
{"num": 457, "time": "00:34:07,960 --> 00:34:11,800", "arabic": "وَأَنْتَ يَا أَحْمَدُ، أَلَا تَخْشَى أَنْ تَبْقَى هُنَا فِي الدَّارِ؟", "segs": [{"ar": "وَأَنْتَ يَا أَحْمَدُ،", "uz": "Sen-chi, Ahmad,"}, {"ar": "أَلَا تَخْشَى أَنْ تَبْقَى هُنَا فِي الدَّارِ؟", "uz": "bu yerda uyda qolishdan qo'rqmaysanmi?"}], "full_uz": "Sen-chi, Ahmad, bu yerda uyda qolishdan qo'rqmaysanmi?", "note": null},
{"num": 458, "time": "00:34:11,800 --> 00:34:13,920", "arabic": "لَيْسَ لَهُمْ عِنْدِي شَيْءٌ يَا رَيْحَانَةُ.", "segs": null, "full_uz": "Ularning menda hech qanday ishi yo'q, ey Rayhona.", "note": null},
{"num": 459, "time": "00:34:13,920 --> 00:34:18,280", "arabic": "لَوْ رَأَيْتَ خَرَجْتَ إِلَى دَارِ عَمِّي إِسْحَاقَ حَتَّى تَهْدَأَ الْأُمُورُ يَا أَبِي.", "segs": [{"ar": "لَوْ رَأَيْتَ خَرَجْتَ إِلَى دَارِ عَمِّي", "uz": "Vaziyat tinchlanguncha amakim Ishoqning uyiga chiqib tursangiz,"}, {"ar": "إِسْحَاقَ حَتَّى تَهْدَأَ الْأُمُورُ يَا أَبِي.", "uz": "dadajon."}], "full_uz": "Vaziyat tinchlanguncha amakim Ishoqning uyiga chiqib tursangiz, dadajon.", "note": null},
{"num": 460, "time": "00:34:18,280 --> 00:34:26,099", "arabic": "أَنَا لَنْ أَبْرَحَ بَعْدَ الْيَوْمِ بَيْتِي، قُلْ لَنْ يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا.", "segs": [{"ar": "أَنَا لَنْ أَبْرَحَ بَعْدَ الْيَوْمِ بَيْتِي،", "uz": "Men bugundan keyin uyimdan chiqmayman. Aytki,"}, {"ar": "قُلْ لَنْ يُصِيبَنَا إِلَّا مَا كَتَبَ اللَّهُ لَنَا.", "uz": "bizga faqat Alloh yozgan narsagina yetadi."}], "full_uz": "Men bugundan keyin uyimdan chiqmayman. Aytki, bizga faqat Alloh yozgan narsagina yetadi.", "note": "Qur'on, Tavba surasi, 51-oyat."},
{"num": 463, "time": "00:35:07,960 --> 00:35:37,960", "arabic": "يَا وَلَدِي!", "segs": null, "full_uz": "Voy, o'g'lim!", "note": null},
{"num": 464, "time": "00:35:37,960 --> 00:35:47,679", "arabic": "حَتَّى عُمَيْرٌ تَأَخَّرَ، لَا تَظُنُّونَ أَنَّهُمْ قَبَضُوا عَلَيْهِ هُوَ الْآخَرُ؟ أَلَا تُرِيحُنَا بِسُكُوتِكَ أَنْتَ؟ لَا نَسْمَعُ مِنْكَ إِلَّا فَأْلَ السُّوءِ.", "segs": [{"ar": "حَتَّى عُمَيْرٌ تَأَخَّرَ، لَا تَظُنُّونَ أَنَّهُمْ قَبَضُوا عَلَيْهِ هُوَ الْآخَرُ؟", "uz": "Umayr ham kechikdi, uni ham qo'lga olishmadimikin, deb o'ylamayapsizlarmi?"}, {"ar": "أَلَا تُرِيحُنَا بِسُكُوتِكَ أَنْتَ؟", "uz": "Sen sukut saqlab, bizni tinch qo'ymaysanmi?"}, {"ar": "لَا نَسْمَعُ مِنْكَ إِلَّا فَأْلَ السُّوءِ.", "uz": "Sendan faqat yomon fol eshitamiz."}], "full_uz": "Umayr ham kechikdi, uni ham qo'lga olishmadimikin, deb o'ylamayapsizlarmi? Sen sukut saqlab, bizni tinch qo'ymaysanmi? Sendan faqat yomon fol eshitamiz.", "note": null},
{"num": 468, "time": "00:35:47,679 --> 00:35:49,760", "arabic": "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.", "segs": null, "full_uz": "Assalomu alaykum va rahmatullohi va barakatuh.", "note": null},
{"num": 469, "time": "00:35:49,760 --> 00:35:51,220", "arabic": "وَعَلَيْكُمُ السَّلَامُ.", "segs": null, "full_uz": "Va alaykum assalom.", "note": null},
{"num": 471, "time": "00:35:51,220 --> 00:35:52,860", "arabic": "لِمَاذَا تَأَخَّرْتَ يَا وَلَدُ؟", "segs": null, "full_uz": "Nega kechikding, bolam?", "note": null},
{"num": 472, "time": "00:35:52,860 --> 00:35:57,679", "arabic": "مَرَرْتُ بِمَرْوَانَةَ أَسْأَلُهُ عَنْ عُمَرَ، وَأَخْبَرَنِي أَنَّهُ بِمَكَانٍ آمِنٍ.", "segs": null, "full_uz": "Marvana oldiga borib, Umar haqida so'radim, u menga uning xavfsiz joyda ekanini aytdi.", "note": null},
{"num": 474, "time": "00:35:57,679 --> 00:36:02,280", "arabic": "الْحَمْدُ لِلَّهِ.", "segs": null, "full_uz": "Alhamdulillah.", "note": null},
{"num": 476, "time": "00:36:07,960 --> 00:36:20,659", "arabic": "لَا بُدَّ أَنَّهَا وِشَايَةٌ، آهِ لَوْ أَعْرِفُ مَنِ الَّذِي وَشَى بِنَا.", "segs": [{"ar": "لَا بُدَّ أَنَّهَا وِشَايَةٌ،", "uz": "Bu albatta bir chaqimchilikdir,"}, {"ar": "آهِ لَوْ أَعْرِفُ مَنِ الَّذِي وَشَى بِنَا.", "uz": "oh, kim bizni sotganini bilsam edi."}], "full_uz": "Bu albatta bir chaqimchilikdir, oh, kim bizni sotganini bilsam edi.", "note": null},
{"num": 478, "time": "00:36:20,659 --> 00:36:40,079", "arabic": "أَكْثَرُ مَا أَخْشَاهُ أَنْ لَا يَقِفَ أَهْلُ بَغْدَادَ فِي وَجْهِ الْمُعْتَزِلَةِ بَعْدَ أَنْ رَأَوْا مَا حَدَثَ بِنَا، أَخْشَى أَنْ يَمْنَعَهُمْ خَوْفُهُمْ عَنْ قَوْلِ كَلِمَةِ الْحَقِّ.", "segs": [{"ar": "أَكْثَرُ مَا أَخْشَاهُ أَنْ", "uz": "Eng ko'p qo'rqadigan narsam"}, {"ar": "لَا يَقِفَ أَهْلُ بَغْدَادَ فِي", "uz": "— bizga bo'lgan voqeani"}, {"ar": "وَجْهِ الْمُعْتَزِلَةِ بَعْدَ أَنْ", "uz": "ko'rgandan keyin Bag'dod ahli"}, {"ar": "رَأَوْا مَا حَدَثَ بِنَا،", "uz": "Mu'taziliga qarshi turmasligidir. Qo'rqamanki,"}, {"ar": "أَخْشَى أَنْ يَمْنَعَهُمْ خَوْفُهُمْ عَنْ قَوْلِ كَلِمَةِ الْحَقِّ.", "uz": "qo'rquvlari ularni haq so'zni aytishdan to'sadi."}], "full_uz": "Eng ko'p qo'rqadigan narsam — bizga bo'lgan voqeani ko'rgandan keyin Bag'dod ahli Mu'taziliga qarshi turmasligidir. Qo'rqamanki, qo'rquvlari ularni haq so'zni aytishdan to'sadi.", "note": null},
{"num": 482, "time": "00:36:40,079 --> 00:36:59,740", "arabic": "هَذَا طَعَامُكَ الَّذِي لَا تَسْتَحِقُّ، فَأَمْثَالُكَ مِنَ الْخَوَنَةِ لَا يَسْتَحِقُّونَ إِلَّا الْمَوْتَ.", "segs": [{"ar": "هَذَا طَعَامُكَ الَّذِي لَا تَسْتَحِقُّ،", "uz": "Mana bu senga loyiq bo'lmagan taomingdir,"}, {"ar": "فَأَمْثَالُكَ مِنَ الْخَوَنَةِ لَا يَسْتَحِقُّونَ إِلَّا الْمَوْتَ.", "uz": "sening kabi xoinlar faqat o'limga loyiqdirlar."}], "full_uz": "Mana bu senga loyiq bo'lmagan taomingdir, sening kabi xoinlar faqat o'limga loyiqdirlar.", "note": null},
{"num": 485, "time": "00:36:59,739 --> 00:37:10,239", "arabic": "تَأَدَّبْ يَا هَذَا، أَلَا تَعْرِفُ مَعَ مَنْ تَتَحَدَّثُ؟", "segs": null, "full_uz": "Odobli bo'l, kim bilan gaplashayotganingni bilmaysanmi?", "note": null},
{"num": 487, "time": "00:37:10,239 --> 00:37:24,559", "arabic": "بَلَى، أَعْرِفُكَ وَأَعْرِفُ أَعْوَانَكَ جَيِّدًا، أَنْتُمْ مَنْ خَرَجْتُمْ عَلَى أَمِيرِ الْمُؤْمِنِينَ حَتَّى أَصْبَحْتُمْ غُرَبَاءَ بَيْنَنَا، وَمَصِيرُكُمُ الْمَوْتُ حَتْمًا.", "segs": [{"ar": "بَلَى، أَعْرِفُكَ وَأَعْرِفُ أَعْوَانَكَ جَيِّدًا،", "uz": "Bilaman, seni va sherikchalaringni yaxshi"}, {"ar": "أَنْتُمْ مَنْ خَرَجْتُمْ عَلَى أَمِيرِ الْمُؤْمِنِينَ حَتَّى أَصْبَحْتُمْ غُرَبَاءَ بَيْنَنَا،", "uz": "taniyman. Sizlar mo'minlar amiriga qarshi chiqib, orangizda g'aribga aylanib qoldingizlar,"}, {"ar": "وَمَصِيرُكُمُ الْمَوْتُ حَتْمًا.", "uz": "va taqdiringiz albatta o'limdir."}], "full_uz": "Bilaman, seni va sherikchalaringni yaxshi taniyman. Sizlar mo'minlar amiriga qarshi chiqib, orangizda g'aribga aylanib qoldingizlar, va taqdiringiz albatta o'limdir.", "note": null},
{"num": 492, "time": "00:37:25,739 --> 00:37:52,139", "arabic": "قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بَدَأَ الْإِسْلَامُ غَرِيبًا، ثُمَّ يَعُودُ غَرِيبًا كَمَا بَدَأَ، فَطُوبَى لِلْغُرَبَاءِ، قِيلَ: يَا رَسُولَ اللَّهِ، وَمَنِ الْغُرَبَاءُ؟ قَالَ: الَّذِينَ يُصْلِحُونَ إِذَا فَسَدَ النَّاسُ.", "segs": [{"ar": "قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بَدَأَ الْإِسْلَامُ غَرِيبًا،", "uz": "Rasululloh (sollallohu alayhi va sallam) aytdi: \"Islom g'arib boshlangan,\""}, {"ar": "ثُمَّ يَعُودُ غَرِيبًا كَمَا بَدَأَ، فَطُوبَى لِلْغُرَبَاءِ،", "uz": "so'ng boshlanganidek yana g'arib bo'lib qaytadi, g'ariblarga xushxabar bo'lsin,\""}, {"ar": "قِيلَ: يَا رَسُولَ اللَّهِ، وَمَنِ الْغُرَبَاءُ؟", "uz": "\"Ey Rasululloh, g'ariblar kimlar?\" deb so'rashdi,"}, {"ar": "قَالَ: الَّذِينَ يُصْلِحُونَ إِذَا فَسَدَ النَّاسُ.", "uz": "U: \"Odamlar buzilganda isloh qiluvchilardir\" dedi."}], "full_uz": "Rasululloh (sollallohu alayhi va sallam) aytdi: \"Islom g'arib boshlangan, so'ng boshlanganidek yana g'arib bo'lib qaytadi, g'ariblarga xushxabar bo'lsin.\" \"Ey Rasululloh, g'ariblar kimlar?\" deb so'rashdi. U: \"Odamlar buzilganda isloh qiluvchilardir\" dedi.", "note": "Sahih Muslimdagi mashhur \"g'urabo\" hadisi."},
{"num": 501, "time": "00:38:21,940 --> 00:38:32,940", "arabic": "حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ.", "segs": null, "full_uz": "Alloh bizga kifoya qiladi, U qanday ham yaxshi vakildir.", "note": null},
{"num": 503, "time": "00:38:37,940 --> 00:38:41,940", "arabic": "لَنْ يَتْرُكُوهُ يَخْرُجُ حَيًّا.", "segs": null, "full_uz": "Uni tirik chiqishga qo'yishmaydi.", "note": null},
{"num": 505, "time": "00:38:43,940 --> 00:38:51,960", "arabic": "إِنَّ الْمُعْتَزِلَةَ يَتَرَبَّصُونَ بِهِ الدَّوَائِرَ مُنْذُ دَهْرٍ، وَلَكِنَّهُمْ لَمْ يَجِدُوا عَلَيْهِ سَبِيلًا.", "segs": [{"ar": "إِنَّ الْمُعْتَزِلَةَ يَتَرَبَّصُونَ بِهِ الدَّوَائِرَ مُنْذُ دَهْرٍ،", "uz": "Mu'tazila anchadan beri unga qarshi fursat poylab kelayapti,"}, {"ar": "وَلَكِنَّهُمْ لَمْ يَجِدُوا عَلَيْهِ سَبِيلًا.", "uz": "lekin unga yo'l topa olishmagan edi."}], "full_uz": "Mu'tazila anchadan beri unga qarshi fursat poylab kelayapti, lekin unga yo'l topa olishmagan edi.", "note": null},
{"num": 507, "time": "00:38:51,960 --> 00:38:59,539", "arabic": "أَمَّا الْآنَ فَقَدْ وَقَعَ بَيْنَ أَيْدِيهِمْ، فَرَّجَ اللَّهُ كُرْبَتَهُ.", "segs": null, "full_uz": "Endi esa u ularning qo'liga tushdi, Alloh uning g'amini yorsin.", "note": null},
{"num": 509, "time": "00:38:59,539 --> 00:39:08,500", "arabic": "مَا عَرَفْتُهُ إِلَّا عَلَى دِينِهِ غَيُورًا، حَرِيصًا عَلَى سُنَّةِ رَسُولِهِ، غَاضِبًا لِلْحَقِّ وَعَلَى أَهْلِ الْبَاطِلِ.", "segs": [{"ar": "مَا عَرَفْتُهُ إِلَّا عَلَى دِينِهِ غَيُورًا،", "uz": "Men uni faqat diniga g'ayratli, Payg'ambarining sunnatiga sodiq,"}, {"ar": "حَرِيصًا عَلَى سُنَّةِ رَسُولِهِ،", "uz": "haq uchun g'azablanadigan va"}, {"ar": "غَاضِبًا لِلْحَقِّ وَعَلَى أَهْلِ الْبَاطِلِ.", "uz": "botil ahliga qarshi ekanligini bilaman."}], "full_uz": "Men uni faqat diniga g'ayratli, Payg'ambarining sunnatiga sodiq, haq uchun g'azablanadigan va botil ahliga qarshi ekanligini bilaman.", "note": null},
{"num": 512, "time": "00:39:08,500 --> 00:39:16,340", "arabic": "لَوْ تَدْرِي يَا أَبَا عَبْدِ اللَّهِ، لَوْ أَنَّكَ كُنْتَ مَعَهُ لَخَرَجَتْ بَغْدَادُ كُلُّهَا خَلْفَكُمْ.", "segs": [{"ar": "لَوْ تَدْرِي يَا أَبَا عَبْدِ اللَّهِ،", "uz": "Bilsangiz edi, ey Abu Abdulloh,"}, {"ar": "لَوْ أَنَّكَ كُنْتَ مَعَهُ لَخَرَجَتْ بَغْدَادُ كُلُّهَا خَلْفَكُمْ.", "uz": "agar siz u bilan birga bo'lganingizda, butun Bag'dod ortingizdan chiqqan bo'lardi."}], "full_uz": "Bilsangiz edi, ey Abu Abdulloh, agar siz u bilan birga bo'lganingizda, butun Bag'dod ortingizdan chiqqan bo'lardi.", "note": null},
{"num": 514, "time": "00:39:16,340 --> 00:39:30,640", "arabic": "أَحْمَدُ بْنُ نَصْرٍ هَذَا مِنْ أَهْلِ الْعِلْمِ وَالدِّيَانَةِ، إِنَّهُ صَاحِبُ اجْتِهَادٍ فِي الْخَيْرِ وَالْعَمَلِ الصَّالِحِ، بَلْ إِنَّهُ مِنْ أَئِمَّةِ السُّنَّةِ الْآمِرِينَ بِالْمَعْرُوفِ وَالنَّاهِينَ عَنِ الْمُنْكَرِ.", "segs": [{"ar": "أَحْمَدُ بْنُ نَصْرٍ هَذَا مِنْ أَهْلِ الْعِلْمِ وَالدِّيَانَةِ،", "uz": "Bu Ahmad ibn Nasr ilm va din ahlidan,"}, {"ar": "إِنَّهُ صَاحِبُ اجْتِهَادٍ فِي الْخَيْرِ وَالْعَمَلِ الصَّالِحِ،", "uz": "u yaxshilik va solih amalda ijtihod egasidir,"}, {"ar": "بَلْ إِنَّهُ مِنْ أَئِمَّةِ السُّنَّةِ الْآمِرِينَ بِالْمَعْرُوفِ وَالنَّاهِينَ عَنِ الْمُنْكَرِ.", "uz": "hatto u yaxshilikka buyuruvchi va yomonlikdan qaytaruvchi sunna imomlaridandir."}], "full_uz": "Bu Ahmad ibn Nasr ilm va din ahlidan, u yaxshilik va solih amalda ijtihod egasidir, hatto u yaxshilikka buyuruvchi va yomonlikdan qaytaruvchi sunna imomlaridandir.", "note": null},
{"num": 518, "time": "00:39:30,640 --> 00:39:43,800", "arabic": "أَسْأَلُ اللَّهَ أَنْ يَفُكَّ أَسْرَهُ مِنْ سُجُونِ الظَّالِمِينَ سِرًّا وَعَلَنًا، يَا رَبِّ.", "segs": [{"ar": "أَسْأَلُ اللَّهَ أَنْ يَفُكَّ أَسْرَهُ مِنْ سُجُونِ الظَّالِمِينَ سِرًّا وَعَلَنًا،", "uz": "Allohdan uni zolimlarning qamoqlaridan yashirin ham, oshkora ham ozod qilishini so'rayman,"}, {"ar": "يَا رَبِّ.", "uz": "ey Robbim."}], "full_uz": "Allohdan uni zolimlarning qamoqlaridan yashirin ham, oshkora ham ozod qilishini so'rayman, ey Robbim.", "note": null},
{"num": 524, "time": "00:40:13,800 --> 00:41:05,720", "arabic": "قُمْ، أَمِيرُ الْمُؤْمِنِينَ يَطْلُبُكَ أَيُّهَا الْخُزَاعِيُّ.", "segs": null, "full_uz": "Tur, mo'minlar amiri seni chaqiryapti, ey Xuzoiy.", "note": null}
];

